  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `device_id` bigint unsigned NOT NULL,
  `interface_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT 'SNMP ifIndex or ifDescr; empty string for device-level metrics',
  `period_start` date NOT NULL COMMENT 'First day of the monthly aggregation window (e.g. 2026-06-01)',
  `avg_if_in_octets` decimal(20,4) DEFAULT NULL,
  `min_if_in_octets` bigint DEFAULT NULL,
  `max_if_in_octets` bigint DEFAULT NULL,
  `avg_if_out_octets` decimal(20,4) DEFAULT NULL,
  `min_if_out_octets` bigint DEFAULT NULL,
  `max_if_out_octets` bigint DEFAULT NULL,
  `avg_if_in_errors` decimal(20,4) DEFAULT NULL,
  `min_if_in_errors` bigint DEFAULT NULL,
  `max_if_in_errors` bigint DEFAULT NULL,
  `avg_if_out_errors` decimal(20,4) DEFAULT NULL,
  `min_if_out_errors` bigint DEFAULT NULL,
  `max_if_out_errors` bigint DEFAULT NULL,
  `avg_cpu_usage` decimal(5,2) DEFAULT NULL,
  `min_cpu_usage` smallint DEFAULT NULL,
  `max_cpu_usage` smallint DEFAULT NULL,
  `avg_memory_usage` decimal(5,2) DEFAULT NULL,
  `min_memory_usage` smallint DEFAULT NULL,
  `max_memory_usage` smallint DEFAULT NULL,
  `avg_signal_strength` decimal(7,2) DEFAULT NULL,
  `min_signal_strength` int DEFAULT NULL,
  `max_signal_strength` int DEFAULT NULL,
  `avg_latency_ms` decimal(10,2) DEFAULT NULL,
  `min_latency_ms` decimal(10,2) DEFAULT NULL,
  `max_latency_ms` decimal(10,2) DEFAULT NULL,
  `avg_voltage_mv` decimal(12,4) DEFAULT NULL,
  `min_voltage_mv` int DEFAULT NULL,
  `max_voltage_mv` int DEFAULT NULL,
  `avg_temperature_c` decimal(8,4) DEFAULT NULL,
  `min_temperature_c` decimal(6,2) DEFAULT NULL,
  `max_temperature_c` decimal(6,2) DEFAULT NULL,
  `avg_fan_speed_rpm` decimal(10,2) DEFAULT NULL,
  `min_fan_speed_rpm` int DEFAULT NULL,
  `max_fan_speed_rpm` int DEFAULT NULL,
  `avg_if_in_discards` decimal(20,4) DEFAULT NULL,
  `min_if_in_discards` bigint DEFAULT NULL,
  `max_if_in_discards` bigint DEFAULT NULL,
  `avg_if_out_discards` decimal(20,4) DEFAULT NULL,
  `min_if_out_discards` bigint DEFAULT NULL,
  `max_if_out_discards` bigint DEFAULT NULL,
  `avg_sfp_tx_power_dbm` decimal(10,4) DEFAULT NULL,
  `min_sfp_tx_power_dbm` decimal(8,4) DEFAULT NULL,
  `max_sfp_tx_power_dbm` decimal(8,4) DEFAULT NULL,
  `avg_sfp_rx_power_dbm` decimal(10,4) DEFAULT NULL,
  `min_sfp_rx_power_dbm` decimal(8,4) DEFAULT NULL,
  `max_sfp_rx_power_dbm` decimal(8,4) DEFAULT NULL,
  `avg_sfp_temperature_c` decimal(8,4) DEFAULT NULL,
  `min_sfp_temperature_c` decimal(6,2) DEFAULT NULL,
  `max_sfp_temperature_c` decimal(6,2) DEFAULT NULL,
  `avg_ups_battery_pct` decimal(5,2) DEFAULT NULL,
  `min_ups_battery_pct` smallint DEFAULT NULL,
  `max_ups_battery_pct` smallint DEFAULT NULL,
  `avg_ups_runtime_min` decimal(10,2) DEFAULT NULL,
  `min_ups_runtime_min` int DEFAULT NULL,
  `max_ups_runtime_min` int DEFAULT NULL,
  `avg_poe_power_mw` decimal(12,4) DEFAULT NULL,
  `min_poe_power_mw` int DEFAULT NULL,
  `max_poe_power_mw` int DEFAULT NULL,
  `avg_humidity_pct` decimal(7,4) DEFAULT NULL,
  `min_humidity_pct` decimal(5,2) DEFAULT NULL,
  `max_humidity_pct` decimal(5,2) DEFAULT NULL,
  `avg_if_oper_status` decimal(4,2) DEFAULT NULL COMMENT 'Average ifOperStatus (1=up ... 2=down)',
  `min_if_oper_status` tinyint DEFAULT NULL,
  `max_if_oper_status` tinyint DEFAULT NULL,
  `sample_count` int unsigned NOT NULL DEFAULT '0' COMMENT 'Number of daily samples aggregated',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `avg_noise_floor_dbm` decimal(7,2) DEFAULT NULL COMMENT 'Average noise floor dBm',
  `min_noise_floor_dbm` smallint DEFAULT NULL COMMENT 'Min noise floor dBm',
  `max_noise_floor_dbm` smallint DEFAULT NULL COMMENT 'Max noise floor dBm',
  `avg_air_util_pct` decimal(5,2) DEFAULT NULL COMMENT 'Average airtime utilization %',
  `min_air_util_pct` tinyint DEFAULT NULL COMMENT 'Min airtime utilization %',
  `max_air_util_pct` tinyint DEFAULT NULL COMMENT 'Max airtime utilization %',
  `avg_gps_sync_status` decimal(4,2) DEFAULT NULL COMMENT 'Average GPS sync status',
  `min_gps_sync_status` tinyint DEFAULT NULL COMMENT 'Min GPS sync status',
  `max_gps_sync_status` tinyint DEFAULT NULL COMMENT 'Max GPS sync status',
  `avg_snr_db` decimal(7,2) DEFAULT NULL COMMENT 'Average SNR dB',
  `min_snr_db` smallint DEFAULT NULL COMMENT 'Min SNR dB',
  `max_snr_db` smallint DEFAULT NULL COMMENT 'Max SNR dB',
  `avg_ccq_pct` decimal(5,2) DEFAULT NULL COMMENT 'Average CCQ %',
  `min_ccq_pct` smallint DEFAULT NULL COMMENT 'Min CCQ %',
  `max_ccq_pct` smallint DEFAULT NULL COMMENT 'Max CCQ %',
  `avg_tx_rate_mbps` decimal(10,4) DEFAULT NULL COMMENT 'Average Tx rate Mbps',
  `min_tx_rate_mbps` decimal(8,2) DEFAULT NULL COMMENT 'Min Tx rate Mbps',
  `max_tx_rate_mbps` decimal(8,2) DEFAULT NULL COMMENT 'Max Tx rate Mbps',
  `avg_rx_rate_mbps` decimal(10,4) DEFAULT NULL COMMENT 'Average Rx rate Mbps',
  `min_rx_rate_mbps` decimal(8,2) DEFAULT NULL COMMENT 'Min Rx rate Mbps',
  `max_rx_rate_mbps` decimal(8,2) DEFAULT NULL COMMENT 'Max Rx rate Mbps',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_snmp_1month_device_iface_period` (`device_id`,`interface_id`,`period_start`),
  KEY `idx_snmp_1month_period_start` (`period_start`),
  CONSTRAINT `fk_snmp_1month_device` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Monthly SNMP metric aggregates — retained 3 years';

CREATE TABLE `snmp_profile_oids` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `profile_id` bigint unsigned NOT NULL,
  `oid` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SNMP OID to poll e.g. 1.3.6.1.2.1.2.2.1.10',
  `metric_column` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Target column in snmp_metrics: if_in_octets, cpu_usage, signal_strength, etc.',
  `label` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Human-readable label for display',
  `oid_type` enum('gauge','counter','counter64','string','timeticks') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'gauge' COMMENT 'SNMP value type for proper delta/rate calculation',
  `is_per_interface` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'TRUE = walk ifTable with ifIndex, FALSE = scalar',
  `aggregate` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Only meaningful when is_per_interface=TRUE: TRUE means walk this OID subtree and reduce every returned row to ONE averaged device-level value (e.g. multi-core hrProcessorLoad) instead of one row per index (migration 401)',
  `transform` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Optional transform expression e.g. "value / 10", "value * -1"',
  `sort_order` int unsigned NOT NULL DEFAULT '0' COMMENT 'Display ordering within the profile',
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `active_flag` tinyint(1) GENERATED ALWAYS AS (if((`deleted_at` is null),1,NULL)) STORED COMMENT 'NULL when soft-deleted; appended to business unique keys so they ignore soft-deleted rows (migration 361)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_profile_oid` (`profile_id`,`oid`,`active_flag`),
  KEY `idx_snmp_profile_oids_metric` (`metric_column`),
  KEY `idx_snmp_profile_oids_status` (`status`),
  KEY `idx_snmp_profile_oids_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_snmp_profile_oids_profile` FOREIGN KEY (`profile_id`) REFERENCES `snmp_profiles` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `snmp_profiles` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Owning org. NULL = a system profile (is_system=1) or an unattributed legacy row, adoptable on write (migration 440)',
  `is_system` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Ships with VigaBSS: visible to every tenant, editable by none (migration 440)',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Profile name e.g. Ubiquiti airOS, MikroTik RouterOS',
  `manufacturer` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Match devices.manufacturer (NULL = any)',
  `model_pattern` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SQL LIKE pattern to match devices.model (NULL = any)',
  `device_type` enum('outdoor_cpe','indoor_cpe','ptp','ptmp_ap','olt','router','switch','onu','other') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Match devices.type (NULL = any)',
  `snmp_version` enum('v1','v2c','v3') COLLATE utf8mb4_unicode_ci DEFAULT 'v2c' COMMENT 'Preferred SNMP version for this profile',
  `poll_interval_sec` int unsigned NOT NULL DEFAULT '300' COMMENT 'Poll interval in seconds (default 5 min)',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Fallback profile when no manufacturer/model match',
  `description` text COLLATE utf8mb4_unicode_ci,
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `active_flag` tinyint(1) GENERATED ALWAYS AS (if((`deleted_at` is null),1,NULL)) STORED COMMENT 'NULL when soft-deleted; appended to business unique keys so they ignore soft-deleted rows (migration 361)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_snmp_profiles_name` (`organization_id`,`name`,`active_flag`),
  KEY `idx_snmp_profiles_manufacturer` (`manufacturer`),
  KEY `idx_snmp_profiles_status` (`status`),
  KEY `idx_snmp_profiles_deleted_at` (`deleted_at`),
  KEY `idx_snmp_profiles_org` (`organization_id`,`status`),
  CONSTRAINT `fk_snmp_profiles_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `snmp_rollup_state` (
  `rollup_name` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Rollup tier identifier (1hr, 1day)',
  `last_processed` timestamp NULL DEFAULT NULL COMMENT 'High-watermark: last successfully processed timestamp',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`rollup_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `snmp_trap_forwarding_deliveries` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL,
  `organization_epoch` bigint unsigned NOT NULL DEFAULT '0' COMMENT 'Owning organization outbound-delivery epoch at enqueue',
  `rule_id` bigint unsigned DEFAULT NULL,
  `trap_id` bigint unsigned DEFAULT NULL,
  `webhook_id` bigint unsigned DEFAULT NULL,
  `target_type` enum('url','email','webhook') COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_url` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Immutable URL snapshot; never returned by delivery-list API',
  `target_email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Immutable email snapshot; never returned by delivery-list API',
  `payload` json NOT NULL COMMENT 'Allowlisted trap metadata only; never community/credentials/varbind values',
  `is_test` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('pending','processing','retrying','success','dead_letter','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `attempt_number` tinyint unsigned NOT NULL DEFAULT '0',
  `max_attempts` tinyint unsigned NOT NULL DEFAULT '4',
  `recovery_count` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'Bounded same-attempt recovery after an ambiguous final worker crash',
  `http_status_code` smallint unsigned DEFAULT NULL,
  `response_time_ms` int unsigned DEFAULT NULL,
  `last_error` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `next_attempt_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `locked_at` datetime DEFAULT NULL,
  `claim_token` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Per-claim UUID used to reject stale worker outcomes',
  `revoked_at` datetime DEFAULT NULL COMMENT 'Set when a claimed immutable delivery is revoked; the active claim may finish but cannot be recovered',
  `delivered_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_stfd_rule_trap` (`organization_id`,`rule_id`,`trap_id`),
  KEY `idx_stfd_org_created` (`organization_id`,`created_at`),
  KEY `idx_stfd_due` (`status`,`next_attempt_at`),
  KEY `idx_stfd_processing` (`status`,`locked_at`),
  KEY `idx_stfd_rule_created` (`rule_id`,`created_at`),
  KEY `idx_stfd_trap` (`trap_id`),
  KEY `idx_stfd_webhook` (`webhook_id`),
  CONSTRAINT `fk_stfd_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `fk_stfd_rule` FOREIGN KEY (`rule_id`) REFERENCES `snmp_trap_forwarding_rules` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `fk_stfd_trap` FOREIGN KEY (`trap_id`) REFERENCES `snmp_traps` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `fk_stfd_webhook` FOREIGN KEY (`webhook_id`) REFERENCES `webhooks` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `chk_stfd_attempts` CHECK (((`max_attempts` between 1 and 11) and (`attempt_number` <= `max_attempts`) and (`recovery_count` <= 1))),
  CONSTRAINT `chk_stfd_target_shape` CHECK ((((`target_type` = 'email') and (`target_email` is not null) and (`target_url` is null) and (`webhook_id` is null)) or ((`target_type` = 'url') and (`target_url` is not null) and (`target_email` is null) and (`webhook_id` is null)) or ((`target_type` = 'webhook') and (`target_url` is not null) and (`target_email` is null) and (`webhook_id` is not null))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `snmp_trap_forwarding_rules` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `match_trap_type` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'NULL = match all trap types',
  `match_source_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'NULL = match any source IP',
  `match_oid_prefix` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'NULL = match any OID',
  `forward_to_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'HTTP/HTTPS endpoint for forwarding',
  `forward_to_email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Email address for forwarding notification',
  `forward_to_webhook_id` bigint unsigned DEFAULT NULL COMMENT 'Webhook ID for forwarding',
  `transform_template` text COLLATE utf8mb4_unicode_ci COMMENT 'Jinja-style template for body transformation (future use)',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `configuration_reviewed_at` datetime DEFAULT NULL COMMENT 'Set only after the current matcher and destination pass the secure API validator',
  `last_delivery_status` enum('pending','processing','retrying','success','dead_letter','cancelled') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Most recent durable delivery outcome for simple rule-list visibility',
  `last_delivery_at` datetime DEFAULT NULL COMMENT 'Time of the most recent delivery state change',
  `last_error` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Truncated non-sensitive error from the most recent failed delivery',
  `last_delivery_is_test` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'TRUE when the summary reflects an operator-triggered test rather than a received trap',
  PRIMARY KEY (`id`),
  KEY `idx_stfr_org` (`organization_id`),
  KEY `idx_stfr_active` (`is_active`),
  KEY `idx_stfr_deleted_at` (`deleted_at`),
  KEY `idx_stfr_org_active_deleted` (`organization_id`,`is_active`,`deleted_at`),
  KEY `idx_stfr_match_ready` (`organization_id`,`is_active`,`deleted_at`,`configuration_reviewed_at`),
  CONSTRAINT `fk_stfr_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `snmp_trap_ingest_daily_usage` (
  `usage_date` date NOT NULL,
  `scope_type` enum('global','organization') COLLATE utf8mb4_unicode_ci NOT NULL,
  `scope_id` bigint unsigned NOT NULL COMMENT '0 for global; organization ID for organization scope',
  `trap_count` bigint unsigned NOT NULL DEFAULT '0',
  `varbind_bytes` bigint unsigned NOT NULL DEFAULT '0',
  `delivery_count` bigint unsigned NOT NULL DEFAULT '0',
  `metadata_only_count` bigint unsigned NOT NULL DEFAULT '0',
  `dropped_trap_count` bigint unsigned NOT NULL DEFAULT '0',
  `forwarding_skipped_count` bigint unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`usage_date`,`scope_type`,`scope_id`),
  CONSTRAINT `chk_snmp_trap_ingest_scope` CHECK ((((`scope_type` = 'global') and (`scope_id` = 0)) or ((`scope_type` = 'organization') and (`scope_id` > 0))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Install-wide UTC-day SNMP ingest quota; transaction-locked before trap/outbox persistence';

CREATE TABLE `snmp_traps` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `device_id` bigint unsigned DEFAULT NULL,
  `source_ip` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL,
  `trap_type` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'unknown',
  `trap_oid` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `varbinds` json DEFAULT NULL,
  `varbinds_truncated` tinyint(1) NOT NULL DEFAULT '0',
  `varbinds_original_count` smallint unsigned NOT NULL DEFAULT '0',
  `varbinds_truncation_reason` enum('count_limit','size_limit','count_and_size_limit','daily_byte_quota') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `community` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `snmp_version` tinyint unsigned NOT NULL DEFAULT '2',
  `is_acknowledged` tinyint(1) NOT NULL DEFAULT '0',
  `acknowledged_by` bigint unsigned DEFAULT NULL,
  `acknowledged_at` datetime DEFAULT NULL,
  `received_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_snmp_traps_ack_by` (`acknowledged_by`),
  KEY `idx_snmp_traps_org_received` (`organization_id`,`received_at`),
  KEY `idx_snmp_traps_device_received` (`device_id`,`received_at`),
  KEY `idx_snmp_traps_type` (`trap_type`),
  KEY `idx_snmp_traps_received` (`received_at`),
  CONSTRAINT `fk_snmp_traps_ack_by` FOREIGN KEY (`acknowledged_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_snmp_traps_device` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_snmp_traps_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `spectrum_scan_results` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `device_id` bigint unsigned NOT NULL COMMENT 'AP device that performed the scan',
  `scan_type` enum('scheduled','manual','triggered') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual',
  `frequency_start_mhz` int NOT NULL,
  `frequency_end_mhz` int NOT NULL,
  `channel_width_mhz` smallint NOT NULL DEFAULT '20',
  `scan_data` json DEFAULT NULL COMMENT 'Raw spectrum data: [{freq_mhz: N, power_dbm: N}]',
  `peak_interference_dbm` decimal(7,2) DEFAULT NULL,
  `recommended_channel_mhz` int DEFAULT NULL COMMENT 'Clearest channel identified',
  `status` enum('pending','in_progress','completed','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_spectrum_scans_device` (`device_id`),
  KEY `idx_spectrum_scans_org` (`organization_id`),
  KEY `idx_spectrum_scans_status` (`status`),
  KEY `idx_spectrum_scans_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_spectrum_scans_device` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_spectrum_scans_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AP spectrum scan results — raw scan_data JSON + recommendation (§9.3)';

CREATE TABLE `speed_tests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Owning org, denormalised from client/contract/device; NULL = unattributed legacy row, adoptable on write (migration 438)',
  `client_id` bigint unsigned DEFAULT NULL COMMENT 'Client who initiated or is associated with this test; NULL = probe-only',
  `contract_id` bigint unsigned DEFAULT NULL COMMENT 'Contract (service) under test; NULL = not contract-specific',
  `work_order_id` bigint unsigned DEFAULT NULL COMMENT 'Installation work order that produced trusted commissioning evidence; NULL for generic/SLA tests (migration 450)',
  `device_id` bigint unsigned DEFAULT NULL COMMENT 'CPE or probe device that ran the test; NULL = client browser test',
  `test_source` enum('client_portal','technician','automated_probe','external') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'How the test was initiated',
  `server_location` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Test server geographic location or identifier',
  `download_mbps` decimal(10,3) NOT NULL COMMENT 'Measured download speed in Mbps',
  `upload_mbps` decimal(10,3) NOT NULL COMMENT 'Measured upload speed in Mbps',
  `latency_ms` decimal(8,2) DEFAULT NULL COMMENT 'Round-trip latency in milliseconds',
  `jitter_ms` decimal(8,2) DEFAULT NULL COMMENT 'Latency jitter in milliseconds',
  `packet_loss_pct` decimal(5,2) DEFAULT NULL COMMENT 'Packet loss percentage (0.00–100.00)',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Public IP address observed during the test (IPv4 or IPv6)',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT 'Free-text observations or technician comments',
  `tested_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'When the test measurement was taken; defaults to insert time for live-recorded tests',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_speed_tests_client_id` (`client_id`),
  KEY `idx_speed_tests_contract_id` (`contract_id`),
  KEY `idx_speed_tests_device_id` (`device_id`),
  KEY `idx_speed_tests_tested_at` (`tested_at`),
  KEY `idx_speed_tests_test_source` (`test_source`),
  KEY `idx_speed_tests_deleted_at` (`deleted_at`),
  KEY `idx_speed_tests_org` (`organization_id`,`tested_at`),
  KEY `idx_speed_tests_work_order` (`work_order_id`,`tested_at`),
  CONSTRAINT `fk_speed_tests_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_speed_tests_contract` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_speed_tests_device` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_speed_tests_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_speed_tests_work_order` FOREIGN KEY (`work_order_id`) REFERENCES `work_orders` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sso_auth_states` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `state` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Random OAuth 2.0 state parameter',
  `nonce` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'OIDC nonce for replay protection',
  `organization_id` bigint unsigned NOT NULL COMMENT 'Org this auth attempt belongs to',
  `redirect_to` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Optional post-auth redirect URL (for deep links)',
  `expires_at` datetime NOT NULL COMMENT 'Expiry time — reject callbacks after this',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sso_state` (`state`),
  KEY `idx_sso_state_expires` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Short-lived OIDC auth state/nonce store for authorization code flow';

CREATE TABLE `sso_saml_assertions_seen` (
  `organization_id` bigint unsigned NOT NULL,
  `assertion_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ID of the signed SAML Response (or its assertion)',
  `expires_at` datetime NOT NULL COMMENT 'NotOnOrAfter of the assertion; the row can be purged after it',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`organization_id`,`assertion_id`),
  KEY `idx_sso_saml_seen_expires` (`expires_at`),
  CONSTRAINT `fk_sso_saml_seen_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `subscriber_certificates` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Tenant organization; NULL = single-tenant deployment',
  `radius_account_id` bigint unsigned DEFAULT NULL COMMENT 'Linked RADIUS account (radius.id)',
  `client_id` bigint unsigned DEFAULT NULL COMMENT 'Linked subscriber (clients.id)',
  `common_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Certificate CN, typically the RADIUS username',
  `serial_number` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Certificate serial number (hex string)',
  `fingerprint_sha256` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SHA-256 fingerprint of the certificate (hex, no colons)',
  `valid_from` datetime NOT NULL,
  `valid_until` datetime NOT NULL,
  `status` enum('active','revoked','expired') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `revoked_at` datetime DEFAULT NULL,
  `revocation_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_subscriber_certificates_org_id` (`organization_id`),
  KEY `idx_subscriber_certificates_radius_account_id` (`radius_account_id`),
  KEY `idx_subscriber_certificates_client_id` (`client_id`),
  KEY `idx_subscriber_certificates_status` (`status`),
  KEY `idx_subscriber_certificates_valid_until` (`valid_until`),
  CONSTRAINT `fk_subscriber_certificates_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_subscriber_certificates_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_subscriber_certificates_radius_account` FOREIGN KEY (`radius_account_id`) REFERENCES `radius` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `subscriber_consents` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `client_id` bigint unsigned NOT NULL,
  `consent_version` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Privacy notice version, e.g. ''2026-01''',
  `purpose` enum('service_delivery','marketing','analytics','third_party_sharing','lawful_retention') COLLATE utf8mb4_unicode_ci NOT NULL,
  `given_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `withdrawn_at` timestamp NULL DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `channel` enum('web','app','paper','phone','email') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'web',
  `communication_channel` enum('email','sms','whatsapp') COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Optional delivery channel covered by this consent; channel records the capture medium',
  `communication_contact_epoch` bigint unsigned NOT NULL DEFAULT '0' COMMENT 'Client communication-contact epoch captured when consent was granted',
  `source_context` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Workflow that captured the choice, for example installation or portal',
  `service_order_id` bigint unsigned DEFAULT NULL COMMENT 'Service order during which the consent choice was captured',
  `work_order_id` bigint unsigned DEFAULT NULL COMMENT 'Field work order during which the consent choice was captured',
  `signed_document_id` bigint unsigned DEFAULT NULL COMMENT 'Signed acknowledgment that presented this communication choice',
  `captured_by` bigint unsigned DEFAULT NULL COMMENT 'Staff user who recorded the subscriber choice; NULL for self-service/system capture',
  `document_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'SHA-256 of the privacy notice version',
  `privacy_notice_version_id` bigint unsigned DEFAULT NULL COMMENT 'The archived notice text this consent accepted (migration 510)',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_subscriber_consents_org` (`organization_id`),
  KEY `idx_subscriber_consents_client` (`client_id`),
  KEY `idx_subscriber_consents_purpose` (`purpose`),
  KEY `idx_subscriber_consents_given_at` (`given_at`),
  KEY `idx_subscriber_consents_active_channel` (`client_id`,`purpose`,`communication_channel`,`withdrawn_at`),
  KEY `idx_subscriber_consents_service_order` (`service_order_id`),
  KEY `idx_subscriber_consents_work_order` (`work_order_id`),
  KEY `idx_subscriber_consents_signed_document` (`signed_document_id`),
  KEY `idx_subscriber_consents_captured_by` (`captured_by`),
  KEY `idx_subscriber_consents_notice_version` (`privacy_notice_version_id`),
  CONSTRAINT `fk_sub_consents_captured_by` FOREIGN KEY (`captured_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sub_consents_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_sub_consents_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sub_consents_service_order` FOREIGN KEY (`service_order_id`) REFERENCES `service_orders` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sub_consents_signed_document` FOREIGN KEY (`signed_document_id`) REFERENCES `signed_documents` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sub_consents_work_order` FOREIGN KEY (`work_order_id`) REFERENCES `work_orders` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_subscriber_consents_notice_version` FOREIGN KEY (`privacy_notice_version_id`) REFERENCES `privacy_notice_versions` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Aviso de Privacidad consent tracking per subscriber (§16.2)';

CREATE TABLE `subscriber_speed_test_jobs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `contract_id` bigint unsigned NOT NULL,
  `test_server_id` bigint unsigned DEFAULT NULL,
  `requested_by` enum('admin','scheduler','client_portal','api') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'admin',
  `scheduled_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `status` enum('queued','running','completed','failed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'queued',
  `download_mbps` decimal(10,3) DEFAULT NULL COMMENT 'Measured download speed',
  `upload_mbps` decimal(10,3) DEFAULT NULL COMMENT 'Measured upload speed',
  `latency_ms` decimal(8,3) DEFAULT NULL,
  `jitter_ms` decimal(8,3) DEFAULT NULL,
  `packet_loss_pct` decimal(5,2) DEFAULT NULL,
  `protocol` enum('iperf3','speedtest_cli','custom') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `raw_result` json DEFAULT NULL COMMENT 'Full JSON result from test tool',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_sstj_contract` (`contract_id`),
  KEY `idx_sstj_server` (`test_server_id`),
  KEY `idx_sstj_status` (`status`),
  KEY `idx_sstj_org` (`organization_id`),
  KEY `idx_sstj_scheduled` (`scheduled_at`),
  CONSTRAINT `fk_sstj_contract` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_sstj_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_sstj_server` FOREIGN KEY (`test_server_id`) REFERENCES `bandwidth_test_servers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `support_channel_configs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL,
  `channel` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_enabled` tinyint(1) NOT NULL DEFAULT '1',
  `availability_hours` json DEFAULT NULL,
  `handoff_behavior` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'queue',
  `webhook_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `config_json` json DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_channel_config` (`organization_id`,`channel`),
  KEY `idx_scc_org` (`organization_id`),
  CONSTRAINT `fk_scc_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `support_conversations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL,
  `client_id` bigint unsigned NOT NULL,
  `channel` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'web',
  `status` enum('open','escalated','closed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `intent` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `confidence` decimal(4,3) DEFAULT NULL,
  `escalation_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `escalated_at` datetime DEFAULT NULL,
  `ticket_id` bigint unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_sc_org` (`organization_id`),
  KEY `idx_sc_client` (`client_id`),
  KEY `idx_sc_status` (`status`),
  KEY `idx_sc_ticket` (`ticket_id`),
  CONSTRAINT `fk_sc_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_sc_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_sc_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `support_messages` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `conversation_id` bigint unsigned NOT NULL,
  `role` enum('customer','assistant','system') COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `intent` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `confidence` decimal(4,3) DEFAULT NULL,
  `data_sources` json DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_smsg_conv` (`conversation_id`),
  KEY `idx_smsg_created` (`created_at`),
  CONSTRAINT `fk_sm_conversation` FOREIGN KEY (`conversation_id`) REFERENCES `support_conversations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `suspension_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `contract_id` bigint unsigned NOT NULL COMMENT 'Contract affected by this suspension event',
  `client_id` bigint unsigned NOT NULL COMMENT 'Client that owns the contract',
  `suspension_rule_id` bigint unsigned DEFAULT NULL COMMENT 'Rule that triggered the action; NULL = manual action',
  `action` enum('suspended','unsuspended','disconnected','reconnected') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Lifecycle action performed',
  `reason` text COLLATE utf8mb4_unicode_ci COMMENT 'Free-text explanation of why the action was taken',
  `triggered_by` enum('system','manual') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Whether the action was triggered automatically or by a user',
  `performed_by_user_id` bigint unsigned DEFAULT NULL COMMENT 'User who performed the action; NULL = system-triggered',
  `radius_coa_sent` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'TRUE if a RADIUS Change-of-Authorization packet was dispatched',
  `radius_coa_response` text COLLATE utf8mb4_unicode_ci COMMENT 'Raw RADIUS CoA response or error message',
  `related_invoice_id` bigint unsigned DEFAULT NULL COMMENT 'Invoice that caused the suspension (most overdue invoice)',
  `suspended_at` timestamp NOT NULL COMMENT 'Timestamp when the suspend/disconnect action was applied',
  `restored_at` timestamp NULL DEFAULT NULL COMMENT 'Timestamp when service was restored; NULL if still suspended',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_suspension_logs_contract_id` (`contract_id`),
  KEY `idx_suspension_logs_client_id` (`client_id`),
  KEY `idx_suspension_logs_rule_id` (`suspension_rule_id`),
  KEY `idx_suspension_logs_performed_by` (`performed_by_user_id`),
  KEY `idx_suspension_logs_related_invoice` (`related_invoice_id`),
  KEY `idx_suspension_logs_action` (`action`),
  KEY `idx_suspension_logs_contract_created` (`contract_id`,`created_at`),
  CONSTRAINT `fk_suspension_logs_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_suspension_logs_contract` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_suspension_logs_invoice` FOREIGN KEY (`related_invoice_id`) REFERENCES `invoices` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_suspension_logs_rule` FOREIGN KEY (`suspension_rule_id`) REFERENCES `suspension_rules` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_suspension_logs_user` FOREIGN KEY (`performed_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `suspension_rules` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL COMMENT 'Tenant organization that owns this rule',
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Descriptive rule name, e.g. "Suspensión 30 días"',
  `days_past_due` int unsigned NOT NULL COMMENT 'Number of days overdue before this rule triggers',
  `grace_period_days` int unsigned NOT NULL DEFAULT '0' COMMENT 'Additional grace days after trigger before action is executed',
  `action` enum('auto_suspend','notify_only','auto_disconnect','soft_suspend','walled_garden') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Action to perform when rule fires',
  `soft_suspend_download_kbps` int unsigned DEFAULT '128' COMMENT 'Throttled download speed (kbps) applied during soft suspension; NULL = inherit plan default',
  `soft_suspend_upload_kbps` int unsigned DEFAULT '128' COMMENT 'Throttled upload speed (kbps) applied during soft suspension; NULL = inherit plan default',
  `notify_before_days` int unsigned DEFAULT NULL COMMENT 'Send a warning notification this many days before suspension; NULL = no advance notice',
  `apply_to_plan_ids` json DEFAULT NULL COMMENT 'JSON array of plan IDs this rule applies to; NULL = applies to all plans',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'FALSE = rule is disabled and will not be evaluated',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_suspension_rules_organization_id` (`organization_id`),
  KEY `idx_suspension_rules_is_active` (`is_active`),
  KEY `idx_suspension_rules_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_suspension_rules_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `suspension_warning_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL,
  `contract_id` bigint unsigned NOT NULL,
  `invoice_id` bigint unsigned NOT NULL COMMENT 'Overdue invoice the warning was about',
  `rule_id` bigint unsigned NOT NULL COMMENT 'Suspension rule whose window it was in',
  `sent_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_suspension_warning_logs_once` (`contract_id`,`invoice_id`,`rule_id`),
  KEY `idx_suspension_warning_logs_org` (`organization_id`),
  KEY `idx_suspension_warning_logs_invoice` (`invoice_id`),
  KEY `idx_suspension_warning_logs_rule` (`rule_id`),
  CONSTRAINT `fk_suspension_warning_logs_contract` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_suspension_warning_logs_invoice` FOREIGN KEY (`invoice_id`) REFERENCES `invoices` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_suspension_warning_logs_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_suspension_warning_logs_rule` FOREIGN KEY (`rule_id`) REFERENCES `suspension_rules` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Suspension warnings already sent, one per contract, invoice and rule (ASY-19)';

CREATE TABLE `tax_rates` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Tenant organization; NULL = applies to all tenants',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Human-readable label, e.g. "IVA 16%", "Exempt", "GST 5%"',
  `rate` decimal(5,4) NOT NULL COMMENT 'Tax rate as a decimal, e.g. 0.1600 = 16%',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'Optional explanation or legal reference',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Default rate applied to new invoices/quotes when none is selected',
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `default_guard` bigint unsigned GENERATED ALWAYS AS ((case when ((`is_default` = 1) and (`status` = 'active') and (`deleted_at` is null)) then ifnull(`organization_id`,0) else NULL end)) VIRTUAL COMMENT 'One active default per org (0 = global): unique key, NULL when not an active default — migration 427',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tax_rates_default_guard` (`default_guard`),
  KEY `idx_tax_rates_organization_id` (`organization_id`),
  KEY `idx_tax_rates_status` (`status`),
  KEY `idx_tax_rates_is_default` (`is_default`),
  KEY `idx_tax_rates_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_tax_rates_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `tax_rules` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Tenant organization; NULL = applies to all tenants',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `region` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'State, province, or country the rule applies to',
  `postal_codes` varchar(2000) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Comma-separated 5-digit codes and/or ranges this rule applies to, e.g. "21000-22999,88000-88299". NULL = matches no ZIP (rule only applies via is_default) — migration 428',
  `tax_type` enum('vat','sales_tax','gst','other') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sales_tax',
  `rate` decimal(5,4) NOT NULL COMMENT 'Tax rate as a decimal, e.g. 0.0800 = 8%',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Default rule applied when no region match is found',
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_tax_rules_organization_id` (`organization_id`),
  KEY `idx_tax_rules_region` (`region`),
  KEY `idx_tax_rules_status` (`status`),
  KEY `idx_tax_rules_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_tax_rules_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `technician_gps_breadcrumbs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL COMMENT 'Technician user ID (no FK — append-only)',
  `latitude` decimal(10,7) NOT NULL,
  `longitude` decimal(10,7) NOT NULL,
  `accuracy_m` float DEFAULT NULL COMMENT 'GPS horizontal accuracy in metres',
  `recorded_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_tgb_user` (`user_id`),
  KEY `idx_tgb_recorded` (`recorded_at`),
  KEY `idx_tgb_user_recorded` (`user_id`,`recorded_at` DESC)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ticket_ai_triage` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ticket_id` bigint unsigned NOT NULL,
  `suggested_category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `suggested_priority` enum('low','medium','high','critical') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `suggested_resolution` text COLLATE utf8mb4_unicode_ci,
  `kb_article_ids` json DEFAULT NULL COMMENT 'Array of recommended KB article IDs',
  `context_snapshot` json DEFAULT NULL COMMENT 'Redacted context used during triage',
  `processed_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ticket_ai_triage_ticket` (`ticket_id`),
  CONSTRAINT `fk_ticket_ai_triage_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ticket_attachments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ticket_id` bigint unsigned NOT NULL,
  `filename` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `original_filename` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mime_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_size` int unsigned NOT NULL,
  `storage_path` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `uploaded_by` bigint unsigned NOT NULL,
  `organization_id` bigint unsigned NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ticket_attachments_ticket` (`ticket_id`),
  KEY `idx_ticket_attachments_org` (`organization_id`),
  KEY `fk_ticket_attachments_uploader` (`uploaded_by`),
  CONSTRAINT `fk_ticket_attachments_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_ticket_attachments_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ticket_attachments_uploader` FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ticket_comments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ticket_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL COMMENT 'Staff member who posted the comment; NULL for system messages',
  `author_type` enum('staff','client','system') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system' COMMENT 'Who wrote it: staff (user_id), client (client_id) or system (migration 517)',
  `client_id` bigint unsigned DEFAULT NULL COMMENT 'Client who wrote it from the portal or chat (migration 517)',
  `body` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_internal` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = internal note visible only to staff',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ticket_comments_ticket_id` (`ticket_id`),
  KEY `idx_ticket_comments_user_id` (`user_id`),
  KEY `idx_ticket_comments_deleted_at` (`deleted_at`),
  KEY `idx_ticket_comments_client_id` (`client_id`),
  CONSTRAINT `fk_ticket_comments_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_ticket_comments_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ticket_comments_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ticket_escalations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Tenant organization; NULL = single-tenant deployment',
  `ticket_id` bigint unsigned NOT NULL,
  `level` tinyint unsigned NOT NULL DEFAULT '1' COMMENT 'Escalation tier: 1 = L1 support, 2 = L2 tech, 3 = management',
  `escalated_by` bigint unsigned DEFAULT NULL COMMENT 'User who escalated; NULL = automatic (stale-ticket task)',
  `escalated_to` bigint unsigned DEFAULT NULL COMMENT 'User the ticket was escalated to',
  `reason` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Why the ticket was escalated',
  `status` enum('open','acknowledged','resolved') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `acknowledged_at` datetime DEFAULT NULL,
  `resolved_at` datetime DEFAULT NULL,
  `resolution_notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ticket_escalations_organization_id` (`organization_id`),
  KEY `idx_ticket_escalations_ticket_level` (`ticket_id`,`level`),
  KEY `idx_ticket_escalations_status` (`status`),
  KEY `fk_ticket_escalations_escalated_by` (`escalated_by`),
  KEY `fk_ticket_escalations_escalated_to` (`escalated_to`),
  CONSTRAINT `fk_ticket_escalations_escalated_by` FOREIGN KEY (`escalated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_ticket_escalations_escalated_to` FOREIGN KEY (`escalated_to`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_ticket_escalations_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_ticket_escalations_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ticket_relations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ticket_id_a` bigint unsigned NOT NULL,
  `ticket_id_b` bigint unsigned NOT NULL,
  `relation_type` enum('duplicate','related','blocks','blocked_by') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'related',
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ticket_relations_pair` (`ticket_id_a`,`ticket_id_b`,`relation_type`),
  KEY `idx_tr_ticket_a` (`ticket_id_a`),
  KEY `idx_tr_ticket_b` (`ticket_id_b`),
  CONSTRAINT `fk_ticket_relations_ticket_a` FOREIGN KEY (`ticket_id_a`) REFERENCES `tickets` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ticket_relations_ticket_b` FOREIGN KEY (`ticket_id_b`) REFERENCES `tickets` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ticket_sla_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ticket_id` bigint unsigned NOT NULL COMMENT 'Ticket this SLA event belongs to',
  `sla_definition_id` bigint unsigned DEFAULT NULL COMMENT 'SLA definition that set the target; NULL = no formal SLA',
  `event_type` enum('first_response','resolution','escalation','breach_warning','breach') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Type of SLA milestone or event',
  `target_deadline` timestamp NULL DEFAULT NULL COMMENT 'Calculated deadline for this SLA target; NULL = informational event',
  `actual_at` timestamp NULL DEFAULT NULL COMMENT 'Actual timestamp when the event occurred; NULL = not yet achieved',
  `is_breached` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'TRUE = the SLA target was missed',
  `breached_by_minutes` int DEFAULT NULL COMMENT 'Minutes by which the deadline was exceeded (positive = late); NULL = not breached',
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT 'Optional context or explanation for the event',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ticket_sla_events_ticket_id` (`ticket_id`),
  KEY `idx_ticket_sla_events_sla_definition_id` (`sla_definition_id`),
  KEY `idx_ticket_sla_events_event_type` (`event_type`),
  KEY `idx_ticket_sla_events_is_breached` (`is_breached`),
  CONSTRAINT `fk_ticket_sla_events_sla_definition` FOREIGN KEY (`sla_definition_id`) REFERENCES `sla_definitions` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_ticket_sla_events_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `ticket_time_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `ticket_id` bigint unsigned NOT NULL,
  `user_id` bigint unsigned NOT NULL,
  `minutes` int unsigned NOT NULL COMMENT 'Duration worked in minutes',
  `work_date` date NOT NULL,
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ttl_ticket` (`ticket_id`),
  KEY `idx_ttl_user` (`user_id`),
  KEY `idx_ttl_work_date` (`work_date`),
  CONSTRAINT `fk_ticket_time_logs_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ticket_time_logs_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `tickets` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Owning tenant organisation; NULL = single-tenant deployment',
  `client_id` bigint unsigned NOT NULL,
  `contract_id` bigint unsigned DEFAULT NULL COMMENT 'Contract this ticket concerns (NULL = general client-level ticket)',
  `assigned_to` bigint unsigned DEFAULT NULL,
  `subject` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `notes` text COLLATE utf8mb4_unicode_ci COMMENT 'Internal operator notes on this ticket',
  `category` enum('technical','billing','installation','general') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'general' COMMENT 'Ticket taxonomy; billing-category tickets are gated by tickets.view_billing (migration 394)',
  `source` enum('manual','alert','portal','ai_escalated','automation') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'manual' COMMENT 'How the ticket was created (migration 297; automation added by 445)',
  `priority` enum('low','medium','high','critical') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `status` enum('open','in_progress','waiting','resolved','closed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `resolved_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_tickets_client_id` (`client_id`),
  KEY `idx_tickets_contract_id` (`contract_id`),
  KEY `idx_tickets_assigned_to` (`assigned_to`),
  KEY `idx_tickets_status` (`status`),
  KEY `idx_tickets_priority` (`priority`),
  KEY `idx_tickets_client_status` (`client_id`,`status`,`created_at` DESC),
  KEY `idx_tickets_assigned_status` (`assigned_to`,`status`),
  KEY `idx_tickets_deleted_at` (`deleted_at`),
  KEY `idx_tickets_organization_id` (`organization_id`),
  KEY `idx_tickets_org_status_created` (`organization_id`,`status`,`created_at`),
  CONSTRAINT `fk_tickets_assigned_to` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_tickets_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_tickets_contract` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_tickets_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `tls_monitor_state` (
  `id` tinyint unsigned NOT NULL DEFAULT '1' COMMENT 'Always 1 — the certificate is install-wide, so this is a single row',
  `hostname` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Host last checked, from APP_URL',
  `last_success_at` timestamp NULL DEFAULT NULL COMMENT 'Last time the certificate was actually READ',
  `last_failure_at` timestamp NULL DEFAULT NULL COMMENT 'Last time the check could not reach the endpoint',
  `consecutive_failures` int unsigned NOT NULL DEFAULT '0' COMMENT 'Runs since the last successful read; 0 while healthy',
  `last_error` text COLLATE utf8mb4_unicode_ci COMMENT 'Why the last attempt failed',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `tunnel_6rd_configs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `border_relay_ip` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'IPv4 address of the 6rd Border Relay',
  `ipv6_prefix` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Delegated 6rd IPv6 prefix',
  `ipv4_mask_len` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'Number of IPv4 prefix bits shared by all CEs',
  `mtu` int unsigned NOT NULL DEFAULT '1480',
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_6rd_org` (`organization_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `user_network_assignments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Tenant org; NULL = single-tenant deployment',
  `user_id` bigint unsigned NOT NULL COMMENT 'User whose VPN scope this row grants',
  `scope_type` enum('site','nas') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Grain of the scope grant: site=all NASes at a site, nas=single NAS',
  `scope_id` bigint unsigned NOT NULL COMMENT 'sites.id (scope_type=site) or nas.id (scope_type=nas)',
  `created_by` bigint unsigned DEFAULT NULL COMMENT 'Admin user who granted this scope',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL COMMENT 'Soft-delete: scope revoked but row retained for audit',
  `active_flag` tinyint(1) GENERATED ALWAYS AS (if((`deleted_at` is null),1,NULL)) STORED COMMENT 'NULL when soft-deleted; used in business unique key',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_una` (`user_id`,`scope_type`,`scope_id`,`active_flag`) COMMENT 'One active grant per user/scope combination',
  KEY `idx_una_user` (`user_id`,`active_flag`),
  KEY `idx_una_org` (`organization_id`),
  CONSTRAINT `fk_una_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_una_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Admin-granted VPN network scope per user (site or NAS grain); durable not work-order-derived (migration 365)';

CREATE TABLE `user_sessions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `token_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Hashed session or refresh token',
  `token_family` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `expires_at` timestamp NOT NULL,
  `last_active_at` timestamp NULL DEFAULT NULL,
  `consumed_at` timestamp NULL DEFAULT NULL COMMENT 'Set when the refresh token was rotated; a replay revokes the family (migration 509)',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_user_sessions_token` (`token_hash`),
  KEY `idx_user_sessions_user_id` (`user_id`),
  KEY `idx_user_sessions_expires_at` (`expires_at`),
  KEY `idx_user_sessions_token_family` (`token_family`),
  CONSTRAINT `fk_user_sessions_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `user_sso_identities` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL COMMENT 'Organization whose SSO config linked this identity',
  `provider_type` enum('saml','oidc') COLLATE utf8mb4_unicode_ci NOT NULL,
  `issuer` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'OIDC issuer URL or SAML IdP entity ID',
  `subject` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'OIDC sub claim or SAML NameID',
  `identity_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'sha256 hex of issuer + newline + subject',
  `user_id` bigint unsigned NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_user_sso_identity` (`organization_id`,`provider_type`,`identity_hash`),
  UNIQUE KEY `uq_user_sso_identity_user` (`organization_id`,`provider_type`,`user_id`),
  KEY `idx_user_sso_identities_user_id` (`user_id`),
  CONSTRAINT `fk_user_sso_identities_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_user_sso_identities_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Per-organization link from an SSO IdP identity (issuer + subject) to a local user (migration 468)';

CREATE TABLE `users` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Tenant organization this user belongs to; NULL = single-tenant deployment',
  `first_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `password_hash` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` enum('admin','billing','support','technician','readonly') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'support',
  `group_id` bigint unsigned DEFAULT NULL COMMENT 'FK to roles: the user group whose permission set governs this staff account',
  `phone` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `totp_secret` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `totp_enabled` tinyint(1) NOT NULL DEFAULT '0',
  `totp_backup_codes` json DEFAULT NULL,
  `totp_last_used_step` bigint unsigned DEFAULT NULL COMMENT 'Last accepted TOTP time step (unix time / 30); a code is accepted only for a later step (migration 467)',
  `last_login_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `failed_login_attempts` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'Consecutive failed login attempts since last successful login',
  `locked_until` timestamp NULL DEFAULT NULL COMMENT 'Account locked until this timestamp; NULL = not locked',
  `reset_token_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'sha256 hex digest of the password-reset token; NULL when no reset is pending (migration 382)',
  `reset_token_expires` datetime DEFAULT NULL COMMENT 'Reset token expiry, set to NOW()+1hr on request (migration 382)',
  `email_verify_token_hash` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'sha256 hex digest of the pending email-verification token (migration 382)',
  `email_verified_at` datetime DEFAULT NULL COMMENT 'When the user confirmed their email; NULL = unverified. Informational only today -- nothing gates login on it (migration 382)',
  `deleted_at` datetime DEFAULT NULL,
  `active_flag` tinyint(1) GENERATED ALWAYS AS (if((`deleted_at` is null),1,NULL)) STORED COMMENT 'NULL when soft-deleted; appended to business unique keys so they ignore soft-deleted rows (migration 361)',
  `is_install_operator` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Runs this INSTALL (deploy, install-wide settings) — NOT a tenant role. Never settable through the API: absent from User.fillable and from every validation schema (migration 444).',
  `must_change_password` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = the account must set a new password before doing anything else; set for the installer-created administrator (migration 480)',
  `password_changed_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'When the current password was set; password_policies.rotation_days counts from here (migration 494)',
  `token_version` int unsigned NOT NULL DEFAULT '0' COMMENT 'Embedded in access JWTs; bumped to revoke every outstanding access token (migration 482)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_email` (`email`,`active_flag`),
  KEY `idx_users_organization_id` (`organization_id`),
  KEY `idx_users_deleted_at` (`deleted_at`),
  KEY `fk_users_group` (`group_id`),
  KEY `idx_users_reset_token_hash` (`reset_token_hash`),
  KEY `idx_users_email_verify_token_hash` (`email_verify_token_hash`),
  CONSTRAINT `fk_users_group` FOREIGN KEY (`group_id`) REFERENCES `roles` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_users_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `uso_obligations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `obligation_type` enum('universal_service','rural_deployment','social_coverage','network_expansion') COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_metric` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'E.g. homes_passed, coverage_percent',
  `target_value` decimal(15,4) DEFAULT NULL,
  `actual_value` decimal(15,4) DEFAULT NULL,
  `period_start` date NOT NULL,
  `period_end` date NOT NULL,
  `status` enum('pending','in_progress','met','partially_met','missed','reported') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `reported_at` timestamp NULL DEFAULT NULL,
  `authority_ref` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_uso_obligations_org` (`organization_id`),
  KEY `idx_uso_obligations_status` (`status`),
  KEY `idx_uso_obligations_period` (`period_start`,`period_end`),
  CONSTRAINT `fk_uso_obligations_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Universal Service Obligation tracking per obligation period (§16.6)';

CREATE TABLE `vendors` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `contact_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `website` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `address` text COLLATE utf8mb4_unicode_ci,
  `tax_id` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payment_terms` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'e.g. Net 30',
  `currency` char(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USD',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_vendors_org` (`organization_id`),
  KEY `idx_vendors_status` (`status`),
  KEY `idx_vendors_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_vendors_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `vlans` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `site_id` bigint unsigned NOT NULL COMMENT 'Site this VLAN belongs to',
  `vlan_id` smallint unsigned NOT NULL COMMENT 'IEEE 802.1Q VLAN ID (1-4094)',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Descriptive label, e.g. "Client-Data", "Management", "VoIP"',
  `description` text COLLATE utf8mb4_unicode_ci,
  `status` enum('active','reserved','deprecated') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT 'active = in use; reserved = allocated but not yet deployed; deprecated = phasing out',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `active_flag` tinyint(1) GENERATED ALWAYS AS (if((`deleted_at` is null),1,NULL)) STORED COMMENT 'NULL when soft-deleted; appended to business unique keys so they ignore soft-deleted rows (migration 361)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_vlans_site_vlan` (`site_id`,`vlan_id`,`active_flag`),
  KEY `idx_vlans_site_id` (`site_id`),
  KEY `idx_vlans_status` (`status`),
  KEY `idx_vlans_deleted_at` (`deleted_at`),
  KEY `idx_vlans_organization_id` (`organization_id`),
  CONSTRAINT `fk_vlans_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_vlans_site` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_vlans_vlan_id` CHECK ((`vlan_id` between 1 and 4094))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `warehouses` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Tenant organization this warehouse belongs to; NULL = single-tenant deployment',
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Warehouse name (e.g. Main Warehouse, Site B Storage)',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `state` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `country` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'US',
  `zip_code` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `latitude` decimal(10,8) DEFAULT NULL,
  `longitude` decimal(11,8) DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_warehouses_organization_id` (`organization_id`),
  KEY `idx_warehouses_status` (`status`),
  KEY `idx_warehouses_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_warehouses_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `webauthn_credentials` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL COMMENT 'User who owns this credential',
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Tenant organization; NULL = single-tenant deployment',
  `credential_id` varchar(1024) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Base64url-encoded credential ID from authenticator',
  `public_key` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'COSE-encoded public key (base64url)',
  `aaguid` varchar(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Authenticator AAGUID (UUID format)',
  `sign_count` bigint unsigned NOT NULL DEFAULT '0' COMMENT 'Monotonic signature counter for clone detection',
  `transports` json DEFAULT NULL COMMENT 'Supported transports: [usb, nfc, ble, internal, hybrid]',
  `attestation_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'none, self, packed, tpm, android-key, fido-u2f',
  `device_type` enum('platform','cross-platform') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cross-platform',
  `is_backup_eligible` tinyint(1) NOT NULL DEFAULT '0',
  `is_backed_up` tinyint(1) NOT NULL DEFAULT '0',
  `friendly_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User-visible label, e.g. "YubiKey 5C"',
  `last_used_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_webauthn_credentials_credential_id` (`credential_id`(512)),
  KEY `idx_webauthn_credentials_user_id` (`user_id`),
  KEY `idx_webauthn_credentials_org_id` (`organization_id`),
  KEY `idx_webauthn_credentials_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_webauthn_credentials_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_webauthn_credentials_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WebAuthn/FIDO2 hardware key credential registrations per user (§17)';

CREATE TABLE `webhook_deliveries` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `webhook_id` bigint unsigned NOT NULL COMMENT 'Webhook registration this delivery belongs to',
  `organization_epoch` bigint unsigned NOT NULL DEFAULT '0' COMMENT 'Owning organization outbound-delivery epoch at enqueue',
  `event_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Event type that triggered this delivery, e.g. "invoice.created"',
  `payload` json NOT NULL COMMENT 'Full event payload sent in the request body',
  `target_url` varchar(2048) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `http_status_code` smallint unsigned DEFAULT NULL COMMENT 'HTTP status code returned by the target endpoint',
  `response_body` text COLLATE utf8mb4_unicode_ci COMMENT 'Response body from the target endpoint (truncated if large)',
  `response_time_ms` int unsigned DEFAULT NULL COMMENT 'Round-trip HTTP request time in milliseconds',
  `attempt_number` tinyint unsigned NOT NULL DEFAULT '1' COMMENT 'Which attempt this row represents (1 = first try)',
  `recovery_count` tinyint unsigned NOT NULL DEFAULT '0',
  `status` enum('pending','processing','success','failed','retrying','dead_letter') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT 'Delivery outcome status',
  `next_retry_at` timestamp NULL DEFAULT NULL COMMENT 'Scheduled time for the next retry attempt; NULL = no retry pending',
  `locked_at` datetime DEFAULT NULL,
  `claim_token` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `revoked_at` datetime DEFAULT NULL COMMENT 'Set when a claimed immutable delivery is revoked; the active claim may finish but cannot be recovered',
  `delivered_at` timestamp NULL DEFAULT NULL COMMENT 'Timestamp of a successful delivery; NULL if not yet succeeded',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_webhook_deliveries_webhook_id` (`webhook_id`),
  KEY `idx_webhook_deliveries_event_name` (`event_name`),
  KEY `idx_webhook_deliveries_status` (`status`),
  KEY `idx_webhook_deliveries_next_retry_at` (`next_retry_at`),
  KEY `idx_webhook_deliveries_status_created` (`status`,`created_at`),
  KEY `idx_webhook_deliveries_dead_letter` (`status`,`webhook_id`) COMMENT 'Fast lookup for dead-letter deliveries needing manual review',
  KEY `idx_webhook_deliveries_processing` (`status`,`locked_at`),
  CONSTRAINT `fk_webhook_deliveries_webhook` FOREIGN KEY (`webhook_id`) REFERENCES `webhooks` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `webhook_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Resolved tenant org (NULL if not yet matched)',
  `org_dedup` bigint unsigned GENERATED ALWAYS AS (coalesce(`organization_id`,0)) VIRTUAL COMMENT 'Dedup partition: organization_id, or 0 for the global env-var route. VIRTUAL because organization_id has an FK with ON DELETE SET NULL / ON UPDATE CASCADE, which MySQL forbids on a STORED generated column base — migration 417',
  `provider` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Gateway provider name: stripe, conekta, etc.',
  `provider_event_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Unique event ID assigned by the provider',
  `event_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Provider event type, e.g. payment_intent.succeeded',
  `payload` json NOT NULL COMMENT 'Full raw event payload from the provider',
  `status` enum('received','processing','processed','failed','ignored','no_match') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'received' COMMENT 'Processing status',
  `error_message` text COLLATE utf8mb4_unicode_ci COMMENT 'Error details if processing failed',
  `transaction_id` bigint unsigned DEFAULT NULL COMMENT 'Linked payment_transactions record after reconciliation',
  `processed_at` timestamp NULL DEFAULT NULL COMMENT 'When the event was fully processed',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_webhook_events_orgdedup_provider_event` (`org_dedup`,`provider`,`provider_event_id`),
  KEY `idx_webhook_events_organization_id` (`organization_id`),
  KEY `idx_webhook_events_status` (`status`),
  KEY `idx_webhook_events_event_type` (`event_type`),
  KEY `idx_webhook_events_transaction_id` (`transaction_id`),
  KEY `idx_webhook_events_created_at` (`created_at`),
  CONSTRAINT `fk_webhook_events_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_webhook_events_transaction` FOREIGN KEY (`transaction_id`) REFERENCES `payment_transactions` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `webhooks` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL COMMENT 'Tenant organization that owns this webhook',
  `url` varchar(2048) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Target URL to POST events to',
  `secret_encrypted` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Encrypted HMAC signing secret for payload verification',
  `events` json NOT NULL COMMENT 'JSON array of event names to subscribe to, e.g. ["invoice.created","payment.received"]',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'FALSE = webhook is paused and deliveries will not be attempted',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'Optional human-readable description of this webhook',
  `max_retries` tinyint unsigned NOT NULL DEFAULT '5' COMMENT 'Maximum number of delivery retry attempts on failure',
  `timeout_seconds` tinyint unsigned NOT NULL DEFAULT '30' COMMENT 'HTTP request timeout in seconds per attempt',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_webhooks_organization_id` (`organization_id`),
  KEY `idx_webhooks_is_active` (`is_active`),
  KEY `idx_webhooks_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_webhooks_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `wg_user_peers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Tenant org; NULL = single-tenant deployment',
  `user_id` bigint unsigned NOT NULL COMMENT 'Owning user (FK -> users.id)',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Human label for the device, e.g. "Laptop" or "Phone"',
  `public_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Client WireGuard public key (base64 x25519)',
  `private_key_encrypted` text COLLATE utf8mb4_unicode_ci COMMENT 'Client WireGuard private key, AES-256-GCM via src/utils/encryption.js; returned only to owner on create + /config download',
  `preshared_key_encrypted` text COLLATE utf8mb4_unicode_ci COMMENT 'Optional WireGuard PSK, AES-256-GCM; passed via temp keyfile never argv',
  `tunnel_address` varchar(45) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Allocated /32 host IP within WG_CLIENT_SUBNET (e.g. 10.99.0.5)',
  `allowed_ips_snapshot` json DEFAULT NULL COMMENT 'Last computed scoped CIDR list — audit trail and list display; authoritative ACL is nftables FORWARD chain',
  `endpoint_host` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Snapshot of WG_ENDPOINT_HOST at time of issue',
  `server_peer_synced` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 when wg set wg-clients peer has been called for this user device',
  `full_tunnel` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=full-tunnel (AllowedIPs 0.0.0.0/0,::/0); 0=split-tunnel (scoped CIDRs); DEFAULT 1 for new peers',
  `last_handshake_at` datetime DEFAULT NULL COMMENT 'Last WireGuard handshake timestamp (live-read for MVP; poller persists in FOLLOW-UP)',
  `rx_bytes` bigint unsigned DEFAULT NULL COMMENT 'Bytes received from this peer (from wg show dump; FOLLOW-UP poller)',
  `tx_bytes` bigint unsigned DEFAULT NULL COMMENT 'Bytes sent to this peer (from wg show dump; FOLLOW-UP poller)',
  `revoked_at` datetime DEFAULT NULL COMMENT 'When the peer was revoked (soft-delete sets deleted_at; revoked_at is the revocation business timestamp)',
  `revoked_by` bigint unsigned DEFAULT NULL COMMENT 'User id that performed the revocation (NULL = self-revoke)',
  `last_error` text COLLATE utf8mb4_unicode_ci COMMENT 'Last sync or firewall error',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `active_flag` tinyint(1) GENERATED ALWAYS AS (if((`deleted_at` is null),1,NULL)) STORED COMMENT 'NULL when soft-deleted; used in business unique keys',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_wg_user_ip` (`tunnel_address`,`active_flag`) COMMENT 'No two active peers share the same tunnel IP',
  UNIQUE KEY `uq_wg_user_pubkey` (`public_key`,`active_flag`) COMMENT 'No two active peers share the same public key',
  KEY `idx_wg_user` (`user_id`,`active_flag`),
  KEY `idx_wg_user_org` (`organization_id`),
  CONSTRAINT `fk_wgu_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_wgu_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='User WireGuard peer devices — one row per enrolled device per user (migration 365)';

CREATE TABLE `whatsapp_conversation_state` (
  `phone_e164` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `client_id` bigint unsigned DEFAULT NULL,
  `state` varchar(40) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'e.g. await_contract_pick, await_problem_desc',
  `context` json DEFAULT NULL COMMENT 'flow scratch data (contract list, chosen contract, ...)',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`phone_e164`),
  KEY `idx_wa_convstate_client` (`client_id`),
  CONSTRAINT `fk_wa_convstate_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WhatsApp bot multi-turn conversation state (migration 419) — one in-flight flow per phone, short-lived.';

CREATE TABLE `whatsapp_inbound_messages` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Resolved once the sender is bound',
  `client_id` bigint unsigned DEFAULT NULL,
  `provider` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'twilio | meta',
  `provider_message_id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone_e164` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `to_number` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Business number that received the message — reserved for future per-org routing',
  `body` text COLLATE utf8mb4_unicode_ci,
  `received_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_wa_inbound_provider_msg` (`provider`,`provider_message_id`),
  KEY `idx_wa_inbound_phone` (`phone_e164`),
  KEY `idx_wa_inbound_received` (`received_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Inbound WhatsApp message audit + dedup (migration 418).';

CREATE TABLE `whatsapp_links` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Org of the bound client; NULL = single-tenant. Data only — inbound resolution is by phone, install-wide.',
  `client_id` bigint unsigned NOT NULL,
  `phone_e164` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Normalized E.164, e.g. +5215512345678',
  `bound_via` enum('portal','email_otp','staff') COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('active','revoked') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `active_phone` varchar(20) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS ((case when (`status` = 'active') then `phone_e164` else NULL end)) VIRTUAL COMMENT 'phone_e164 while active, else NULL — powers the one-active-binding-per-phone UNIQUE without blocking revoked history',
  `bound_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `last_seen_at` datetime DEFAULT NULL COMMENT 'Last inbound message from this bound number',
  `revoked_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_whatsapp_links_active_phone` (`active_phone`),
  KEY `idx_whatsapp_links_client` (`client_id`),
  KEY `idx_whatsapp_links_phone` (`phone_e164`),
  KEY `fk_whatsapp_links_org` (`organization_id`),
  CONSTRAINT `fk_whatsapp_links_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_whatsapp_links_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='WhatsApp number -> client binding (migration 418). One active binding per phone install-wide.';

CREATE TABLE `whatsapp_verifications` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL,
  `phone_e164` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Target phone; NULL for portal-minted codes (phone unknown until the client texts it)',
  `purpose` enum('link_portal','link_email','stepup') COLLATE utf8mb4_unicode_ci NOT NULL,
  `client_id` bigint unsigned DEFAULT NULL COMMENT 'Resolved target client (known at mint time for portal codes / after email match)',
  `code_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'sha256(code + server pepper) hex — NEVER the plaintext code',
  `channel` enum('email','portal') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Where the code was delivered',
  `expires_at` datetime NOT NULL,
  `consumed_at` datetime DEFAULT NULL,
  `attempts` int NOT NULL DEFAULT '0' COMMENT 'Wrong-code attempts against this row',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_wa_verif_phone_purpose` (`phone_e164`,`purpose`,`consumed_at`),
  KEY `idx_wa_verif_purpose_codehash` (`purpose`,`code_hash`),
  KEY `idx_wa_verif_expires` (`expires_at`),
  KEY `fk_wa_verif_client` (`client_id`),
  KEY `fk_wa_verif_org` (`organization_id`),
  CONSTRAINT `fk_wa_verif_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_wa_verif_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Short-lived WhatsApp linking / step-up codes (migration 418) — hashed, single-use, expiring.';

CREATE TABLE `winback_campaigns` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Tenant organization; NULL = single-tenant deployment',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('draft','active','paused','completed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `target_segment` enum('all_cancelled','cancelled_30d','cancelled_90d','high_value') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'all_cancelled' COMMENT 'Which cancelled-customer cohort this campaign targets',
  `offer_description` text COLLATE utf8mb4_unicode_ci,
  `discount_percent` decimal(5,2) DEFAULT NULL COMMENT 'Retention discount offered (0-100)',
  `message_template_id` bigint unsigned DEFAULT NULL COMMENT 'Message template used for outreach',
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_winback_campaigns_organization_id` (`organization_id`),
  KEY `idx_winback_campaigns_status` (`status`),
  KEY `idx_winback_campaigns_deleted_at` (`deleted_at`),
  KEY `fk_winback_campaigns_template` (`message_template_id`),
  CONSTRAINT `fk_winback_campaigns_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_winback_campaigns_template` FOREIGN KEY (`message_template_id`) REFERENCES `message_templates` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `wireless_channel_interference` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Tenant organization',
  `ap_sector_config_id` bigint unsigned DEFAULT NULL COMMENT 'AP sector where interference was detected',
  `site_id` bigint unsigned DEFAULT NULL COMMENT 'Site where interference was detected',
  `detected_at` datetime NOT NULL COMMENT 'When interference was observed',
  `frequency_mhz` int DEFAULT NULL COMMENT 'Affected frequency in MHz',
  `channel_width_mhz` smallint DEFAULT NULL COMMENT 'Affected channel width in MHz',
  `interference_level` enum('low','medium','high','critical') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `conflicting_ap_mac` varchar(17) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MAC of the conflicting AP if known',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_wci_organization_id` (`organization_id`),
  KEY `idx_wci_ap_sector_config_id` (`ap_sector_config_id`),
  KEY `idx_wci_site_id` (`site_id`),
  KEY `idx_wci_detected_at` (`detected_at`),
  KEY `idx_wci_interference_level` (`interference_level`),
  KEY `idx_wci_deleted_at` (`deleted_at`),
  CONSTRAINT `fk_wci_ap_sector_config` FOREIGN KEY (`ap_sector_config_id`) REFERENCES `ap_sector_configs` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_wci_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_wci_site` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Detected RF channel interference records per sector/site';

CREATE TABLE `wireless_client_sessions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned DEFAULT NULL COMMENT 'Tenant organization',
  `device_id` bigint unsigned NOT NULL COMMENT 'AP device that observed this client',
  `client_device_id` bigint unsigned DEFAULT NULL COMMENT 'CPE device record (NULL if unknown)',
  `mac_address` varchar(17) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Client MAC address (AA:BB:CC:DD:EE:FF)',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Client IP address (IPv4 or IPv6)',
  `signal_dbm` smallint DEFAULT NULL COMMENT 'Received signal level in dBm',
  `noise_floor_dbm` smallint DEFAULT NULL COMMENT 'Noise floor at AP in dBm',
  `snr_db` smallint DEFAULT NULL COMMENT 'Signal-to-noise ratio in dB',
  `ccq_pct` smallint DEFAULT NULL COMMENT 'Client Connection Quality percentage (0–100)',
  `tx_rate_mbps` decimal(8,2) DEFAULT NULL COMMENT 'Transmit rate in Mbps',
  `rx_rate_mbps` decimal(8,2) DEFAULT NULL COMMENT 'Receive rate in Mbps',
  `distance_m` int DEFAULT NULL COMMENT 'Distance from AP in metres',
  `connected_at` datetime DEFAULT NULL COMMENT 'Session association time (NULL if unknown)',
  `last_seen_at` datetime NOT NULL COMMENT 'Timestamp of this observation',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_wcs_organization_id` (`organization_id`),
  KEY `idx_wcs_device_id` (`device_id`),
  KEY `idx_wcs_client_device_id` (`client_device_id`),
  KEY `idx_wcs_mac_address` (`mac_address`),
  KEY `idx_wcs_last_seen_at` (`last_seen_at`),
  CONSTRAINT `fk_wcs_client_device` FOREIGN KEY (`client_device_id`) REFERENCES `devices` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_wcs_device` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_wcs_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Append-only CPE client state snapshots per AP poll';

CREATE TABLE `work_order_attachments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `work_order_id` bigint unsigned NOT NULL,
  `filename` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `original_filename` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mime_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_size` int unsigned NOT NULL,
  `storage_path` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `uploaded_by` bigint unsigned NOT NULL,
  `organization_id` bigint unsigned NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_wo_attachments_work_order` (`work_order_id`),
  KEY `idx_wo_attachments_org` (`organization_id`),
  KEY `fk_wo_attachments_uploader` (`uploaded_by`),
  CONSTRAINT `fk_wo_attachments_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_wo_attachments_uploader` FOREIGN KEY (`uploaded_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_wo_attachments_work_order` FOREIGN KEY (`work_order_id`) REFERENCES `work_orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `work_order_materials` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `work_order_id` bigint unsigned NOT NULL,
  `item_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `quantity` decimal(10,3) NOT NULL DEFAULT '1.000',
  `unit` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'e.g. pcs, m, kg',
  `unit_cost` decimal(12,4) DEFAULT NULL,
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_wom_work_order` (`work_order_id`),
  CONSTRAINT `fk_work_order_materials_work_order` FOREIGN KEY (`work_order_id`) REFERENCES `work_orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `work_orders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL,
  `client_id` bigint unsigned DEFAULT NULL COMMENT 'Subscriber this work order serves (NULL for internal/NOC work)',
  `site_id` bigint unsigned DEFAULT NULL COMMENT 'POP / site this work order targets',
  `device_id` bigint unsigned DEFAULT NULL COMMENT 'Specific device this work order targets',
  `contract_id` bigint unsigned DEFAULT NULL COMMENT 'Contract this work order relates to',
  `service_order_id` bigint unsigned DEFAULT NULL COMMENT 'Originating service order, if spawned from provisioning',
  `ticket_id` bigint unsigned DEFAULT NULL COMMENT 'Source ticket (may be NULL for standalone work orders)',
  `assigned_to` bigint unsigned DEFAULT NULL COMMENT 'Technician assigned to this work order',
  `created_by` bigint unsigned DEFAULT NULL COMMENT 'User who created the work order',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `status` enum('pending','assigned','in_progress','completed','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `priority` enum('low','medium','high','critical') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `work_type` enum('installation','maintenance','repair','survey','pickup','other') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'other' COMMENT 'Field-work classification (migrated from jobs.type); pickup = auto-created equipment-return follow-up on contract cancellation (migration 391)',
  `scheduled_at` datetime DEFAULT NULL COMMENT 'Planned visit datetime',
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `latitude` decimal(10,7) DEFAULT NULL COMMENT 'Job site GPS latitude',
  `longitude` decimal(10,7) DEFAULT NULL COMMENT 'Job site GPS longitude',
  `address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `legacy_job_id` bigint unsigned DEFAULT NULL COMMENT 'Original jobs.id this row was migrated from (migration 363); NULL for natively-created work orders',
  `acceptance_signal_dbm` smallint DEFAULT NULL COMMENT 'Wireless CPE signal (dBm) measured at install handoff (migration 445)',
  `acceptance_link_mbps` decimal(8,2) DEFAULT NULL COMMENT 'Negotiated RF link rate (Mbps) measured at install handoff (migration 445)',
  `acceptance_rx_dbm` decimal(6,2) DEFAULT NULL COMMENT 'FTTH optical Rx power (dBm) measured at install handoff (migration 445)',
  `acceptance_waived` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Explicit skip of acceptance readings on an installation WO; reason goes in acceptance_notes (migration 445)',
  `acceptance_notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Free-text context for the acceptance readings or the waive reason (migration 445)',
  `acceptance_recorded_at` datetime DEFAULT NULL COMMENT 'When acceptance readings (or the waive) were recorded (migration 445)',
  PRIMARY KEY (`id`),
  KEY `idx_wo_organization` (`organization_id`),
  KEY `idx_wo_ticket` (`ticket_id`),
  KEY `idx_wo_assigned` (`assigned_to`),
  KEY `idx_wo_status` (`status`),
  KEY `idx_wo_scheduled` (`scheduled_at`),
  KEY `idx_wo_deleted` (`deleted_at`),
  KEY `fk_work_orders_created_by` (`created_by`),
  KEY `idx_wo_client` (`client_id`),
  KEY `idx_wo_site` (`site_id`),
  KEY `idx_wo_device` (`device_id`),
  KEY `idx_wo_contract` (`contract_id`),
  KEY `idx_wo_service_order` (`service_order_id`),
  KEY `idx_wo_legacy_job` (`legacy_job_id`),
  KEY `idx_wo_org_status_created` (`organization_id`,`status`,`created_at`),
  CONSTRAINT `fk_work_orders_assigned_to` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_work_orders_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_work_orders_contract` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_work_orders_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_work_orders_device` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_work_orders_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_work_orders_service_order` FOREIGN KEY (`service_order_id`) REFERENCES `service_orders` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_work_orders_site` FOREIGN KEY (`site_id`) REFERENCES `sites` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_work_orders_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `xlat464_configs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint unsigned NOT NULL,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `plat_prefix` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'PLAT (Provider-side translator) prefix',
  `clat_prefix` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'CLAT (Customer-side translator) prefix',
  `dns64_prefix` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'DNS64 synthesis prefix',
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active',
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_xlat464_org` (`organization_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

