INSERT INTO `scheduled_tasks` (`id`, `organization_id`, `task_name`, `task_type`, `handler`, `description`, `cron_expression`, `payload`, `priority`, `max_retries`, `retry_count`, `timeout_seconds`, `last_run_at`, `next_run_at`, `last_status`, `last_error`, `last_duration_ms`, `locked_at`, `locked_by`, `is_enabled`, `created_at`, `updated_at`) VALUES (69,NULL,'message_outbox','notification',NULL,'Deliver queued email, SMS, WhatsApp and push messages from message_outbox, with retries and per-organization rate limits.','* * * * *',NULL,'high',3,0,120,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,NOW(),NOW());
INSERT INTO `settings` (`id`, `setting_key`, `setting_value`, `description`, `created_at`, `updated_at`) VALUES (26,'map_tile_url','https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png','XYZ raster tile URL template for all maps. Placeholders: {s} subdomain, {z} zoom, {x}/{y} tile. Blank = OpenStreetMap default. Google Maps is NOT supported here — it requires its own JS API, not a tile URL.',NOW(),NOW());
INSERT INTO `settings` (`id`, `setting_key`, `setting_value`, `description`, `created_at`, `updated_at`) VALUES (27,'map_tile_attribution','&copy; <a href=\"https://www.openstreetmap.org/copyright\">OpenStreetMap</a>','Attribution HTML shown in the map corner. Most tile providers REQUIRE a specific credit — check your provider terms when changing map_tile_url.',NOW(),NOW());
INSERT INTO `settings` (`id`, `setting_key`, `setting_value`, `description`, `created_at`, `updated_at`) VALUES (28,'ops_alert_email','','Where INFRASTRUCTURE alerts go (TLS expiry, host-level failures). One address, or several separated by commas. Blank = fall back to notifying every organization admin/manager, which is noisy on a multi-tenant install.',NOW(),NOW());
INSERT INTO `settings` (`id`, `setting_key`, `setting_value`, `description`, `created_at`, `updated_at`) VALUES (29,'wireguard_server_enabled','migrate','Enable the managed WireGuard hub. The isolated networking helper owns NET_ADMIN; the web/API app remains non-root. Fresh installs use private randomly generated UDP ports.',NOW(),NOW());
