INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,NULL,1,'Generic IF-MIB',NULL,NULL,NULL,'v2c',300,1,'Default fallback profile using standard IF-MIB (RFC 2863) and HOST-RESOURCES-MIB (RFC 2790) OIDs. Applied to any device that does not match a more specific profile.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (2,NULL,1,'Ubiquiti airOS v6 (airMAX M)','Ubiquiti',NULL,NULL,'v2c',300,0,'airMAX M-series CPEs/APs on airOS v6 (PowerBeam M, NanoStation M, Rocket M…). Canonical UBNT-AirMAX-MIB ubntWlStatTable radio health (Signal/Noise/CCQ) + IF-MIB traffic/errors + HOST-RESOURCES CPU/memory. For AC hardware (airOS v8) use the v8 profile.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (3,NULL,1,'MikroTik RouterOS','MikroTik',NULL,NULL,'v2c',300,0,'MikroTik RouterOS devices. Uses MikroTik enterprise MIB (OID prefix 1.3.6.1.4.1.14988) for wireless signal strength in addition to standard IF-MIB interface counters and HOST-RESOURCES-MIB CPU/memory.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (4,NULL,1,'Cambium Networks','Cambium',NULL,NULL,'v2c',300,0,'Cambium Networks devices (ePMP, PMP, cnPilot). Uses Cambium enterprise MIB (OID prefix 1.3.6.1.4.1.161) for RSSI and CPU in addition to standard IF-MIB interface counters.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (5,NULL,1,'Cisco IOS','Cisco',NULL,NULL,'v2c',300,0,'Cisco IOS/IOS-XE routers and switches. Uses CISCO-PROCESS-MIB, CISCO-MEMORY-POOL-MIB, and standard IF-MIB.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (6,NULL,1,'Juniper JunOS','Juniper',NULL,NULL,'v2c',300,0,'Juniper Networks JunOS devices. Uses JUNIPER-MIB and standard IF-MIB.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (7,NULL,1,'Huawei VRP','Huawei',NULL,NULL,'v2c',300,0,'Huawei VRP devices (routers, switches, OLTs). Uses HUAWEI-MIB and standard IF-MIB.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (8,NULL,1,'ZTE ZXAN','ZTE',NULL,NULL,'v2c',300,0,'ZTE OLT/DSLAM devices. Uses ZTE enterprise MIB and standard IF-MIB.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (9,NULL,1,'Generic Switch',NULL,NULL,'switch','v2c',300,0,'Generic switch profile with port status, errors, and PoE OIDs from RFC 3621 and IF-MIB.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (10,NULL,1,'Generic UPS',NULL,NULL,'other','v2c',300,0,'APC/Eaton/generic UPS via RFC 1628 UPS-MIB and vendor extensions.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (11,NULL,1,'SFP Diagnostics',NULL,NULL,'other','v2c',60,0,'SFP/QSFP optical diagnostics via ENTITY-SENSOR-MIB (RFC 3433) for Tx power, Rx power, temperature.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (12,NULL,1,'Environmental Sensors',NULL,NULL,'other','v2c',120,0,'Environmental sensors (temperature, humidity) via ENTITY-SENSOR-MIB.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (13,NULL,1,'Cisco BNG','Cisco','ASR100[0-9]|ASR900[0-9]','router','v2c',300,0,'Cisco Broadband Network Gateway (ASR1000/ASR9000). Uses CISCO-PROCESS-MIB cpmCPU*, CISCO-MEMORY-POOL-MIB, CISCO-SUBSCRIBER-SESSION-MIB for active sessions, and standard IF-MIB for interface throughput/errors.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (14,NULL,1,'Juniper BNG','Juniper','MX[0-9]|ERX','router','v2c',300,0,'Juniper Networks BNG/BRAS (MX-series, ERX). Uses JUNIPER-MIB jnxOperating* for CPU/memory, JUNIPER-SUBSCRIBER-MIB for session counts, and standard IF-MIB.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (15,NULL,1,'Huawei OLT','Huawei','MA5800|EA5800|MA5600','other','v2c',300,0,'Huawei MA5800/EA5800 GPON OLT. Uses HUAWEI-XPON-MIB for ONU counts and PON port Rx power, standard IF-MIB for uplink interface traffic, and HUAWEI-ENTITY-EXTENT-MIB for CPU/memory/temperature.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (16,NULL,1,'ZTE OLT','ZTE','C300|C320|C600|ZXA10','other','v2c',300,0,'ZTE C300/C320/C600 GPON OLT. Uses ZTE ZXAN enterprise MIB (1.3.6.1.4.1.3902) for CPU/memory and ONU registration, plus standard IF-MIB for uplink traffic.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (17,NULL,1,'Mimosa B-series PTP','Mimosa','B%','ptp','v2c',60,0,'Mimosa B-series point-to-point backhaul radios on the 1.x firmware family. Uses the official B5 and C5 product MIB Rev 3.00 plus IF-MIB/IF-X-MIB.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (18,NULL,1,'Tarana Wireless','Tarana','G1|G1A|G1B',NULL,'v2c',60,0,'Tarana Wireless G1 fixed wireless access system. Uses Tarana enterprise MIB (OID prefix 1.3.6.1.4.1.50536) for DL/UL signal, noise floor, SNR, and GPS sync status. Designed for NLOS subscriber connections up to 10 km.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (19,NULL,1,'Radwin','Radwin','2000|5000|JET',NULL,'v2c',60,0,'Radwin 2000/5000 series PTP/PTMP wireless broadband systems. Uses Radwin enterprise MIB (OID prefix 1.3.6.1.4.1.4329) for signal, modulation, airtime utilization, and Tx power. Supports sub-6 GHz and 60 GHz E-band configurations.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (20,NULL,1,'Siklu','Siklu','EH-[0-9]|BreezeULTRA|MultiHaul',NULL,'v2c',60,0,'Siklu E-band / V-band mmWave wireless links. Uses Siklu enterprise MIB (OID prefix 1.3.6.1.4.1.31926) for RSL, TSL, SNR, modulation, and link budget metrics. Primarily used for 60/70/80 GHz multi-gigabit backhaul and last-mile.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (21,NULL,1,'Ubiquiti LiteBeam 5AC Gen2','Ubiquiti','%LBE%5AC%','outdoor_cpe','v2c',300,0,'LiteBeam 5AC Gen2 subscriber CPE (airMAX AC, airOS 8). Radio health from the canonical UBNT-AirMAX-MIB ubntWlStatTable (signal/noise/CCQ, single row index 1) + IF-MIB traffic/errors + HOST-RESOURCES CPU/memory.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (22,NULL,1,'Ubiquiti PowerBeam M5-400','Ubiquiti','%PBE%M5%','outdoor_cpe','v2c',300,0,'PowerBeam M5-400 subscriber CPE (airMAX M, airOS 6). Radio health from the canonical UBNT-AirMAX-MIB ubntWlStatTable (signal/noise/CCQ, single row index 1) + IF-MIB traffic/errors + HOST-RESOURCES CPU/memory.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (23,NULL,1,'Ubiquiti airCube ISP','Ubiquiti','%ACB%','indoor_cpe','v2c',300,0,'airCube ISP indoor router/AP (ACB-ISP). NOT an airMAX device — no ubntWlStat radio table; records IF-MIB traffic/errors + HOST-RESOURCES CPU/memory.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (25,NULL,1,'Ubiquiti airOS v8 (airMAX AC)','Ubiquiti','%AC%',NULL,'v2c',300,0,'airMAX AC CPEs/APs on airOS v8 (LiteBeam AC, PowerBeam AC, NanoBeam AC…). Signal/Noise from ubntWlStatTable; link quality is airMAX Quality (AMQ — CCQ is an M-series metric) + IF-MIB traffic/errors + HOST-RESOURCES CPU/memory.','active',NOW(),NOW(),NULL);
INSERT INTO `snmp_profiles` (`id`, `organization_id`, `is_system`, `name`, `manufacturer`, `model_pattern`, `device_type`, `snmp_version`, `poll_interval_sec`, `is_default`, `description`, `status`, `created_at`, `updated_at`, `deleted_at`) VALUES (26,NULL,1,'Mimosa C5c PTP','Mimosa','%C5c%','ptp','v2c',60,0,'Mimosa C5c radios operating in point-to-point/backhaul mode on the 2.x firmware family. Uses the official B5 and C5 product MIB Rev 3.00 plus IF-MIB/IF-X-MIB.','active',NOW(),NOW(),NULL);
