DROP TRIGGER IF EXISTS `trg_clients_locale_downgrade_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_clients_locale_downgrade_bu` BEFORE UPDATE ON `clients` FOR EACH ROW BEGIN
    DECLARE v_has_mx_profile BOOLEAN DEFAULT FALSE;
    DECLARE v_has_cfdi       BOOLEAN DEFAULT FALSE;

    IF OLD.locale = 'MX' AND NEW.locale != 'MX' THEN
        SELECT EXISTS(SELECT 1 FROM client_mx_profiles WHERE client_id = OLD.id)
        INTO v_has_mx_profile;

        IF v_has_mx_profile THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Cannot change client locale from ''MX'': client_mx_profiles record exists. Delete the MX profile first.';
        END IF;

        SELECT EXISTS(SELECT 1 FROM cfdi_documents WHERE client_id = OLD.id)
        INTO v_has_cfdi;

        IF v_has_cfdi THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Cannot change client locale from ''MX'': cfdi_documents records exist for this client.';
        END IF;
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_clients_communication_contact_epoch_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_clients_communication_contact_epoch_bu` BEFORE UPDATE ON `clients` FOR EACH ROW BEGIN
    IF NOT (BINARY NEW.email <=> BINARY OLD.email)
       OR NOT (NEW.deleted_at <=> OLD.deleted_at)
       OR ((NEW.status = 'inactive') <> (OLD.status = 'inactive')) THEN
        SET NEW.email_contact_epoch = OLD.email_contact_epoch + 1;
    ELSE
        SET NEW.email_contact_epoch = OLD.email_contact_epoch;
    END IF;

    IF NOT (BINARY NEW.phone <=> BINARY OLD.phone)
       OR NOT (NEW.deleted_at <=> OLD.deleted_at)
       OR ((NEW.status = 'inactive') <> (OLD.status = 'inactive')) THEN
        SET NEW.phone_contact_epoch = OLD.phone_contact_epoch + 1;
    ELSE
        SET NEW.phone_contact_epoch = OLD.phone_contact_epoch;
    END IF;
END ;;
DELIMITER ;

