DROP TRIGGER IF EXISTS `trg_contracts_mx_template_bi`;
DELIMITER ;;
CREATE TRIGGER `trg_contracts_mx_template_bi` BEFORE INSERT ON `contracts` FOR EACH ROW BEGIN
  DECLARE contract_org_id BIGINT UNSIGNED DEFAULT NULL;
  DECLARE contract_locale VARCHAR(10) DEFAULT NULL;
  DECLARE current_contract_environment VARCHAR(16) DEFAULT NULL;
  DECLARE source_org_id BIGINT UNSIGNED DEFAULT NULL;

  SELECT client.organization_id INTO contract_org_id
    FROM clients client WHERE client.id = NEW.client_id LIMIT 1;
  SET contract_org_id = COALESCE(NEW.organization_id, contract_org_id);

  SELECT organization_row.locale,
         CASE
           WHEN profile.contract_environment IS NOT NULL THEN profile.contract_environment
           WHEN EXISTS (
             SELECT 1 FROM contract_templates_mx legacy_source
              WHERE legacy_source.organization_id = organization_row.id
                AND legacy_source.environment = 'production'
           ) THEN 'production'
           ELSE 'sandbox'
         END
    INTO contract_locale, current_contract_environment
    FROM organizations organization_row
    LEFT JOIN organization_mx_profiles profile
      ON profile.organization_id = organization_row.id AND profile.deleted_at IS NULL
   WHERE organization_row.id = contract_org_id
   LIMIT 1
   FOR UPDATE;

  IF contract_locale = 'MX' THEN
    IF NEW.contract_template_mx_id IS NULL OR NEW.mx_contract_environment IS NULL THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'MX contracts require a classified contract source and environment';
    END IF;
    IF NEW.mx_contract_environment <> current_contract_environment THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'MX contract environment must match the organization current contract environment';
    END IF;
    SELECT source.organization_id INTO source_org_id
      FROM contract_templates_mx source
     WHERE source.id = NEW.contract_template_mx_id
       AND source.environment = NEW.mx_contract_environment
       AND source.deleted_at IS NULL
       AND (
         (source.environment = 'sandbox'
          AND source.status = 'sandbox_ready'
          AND source.ift_registration_number IS NULL
          AND source.registered_at IS NULL)
         OR (source.environment = 'production'
          AND source.status = 'registered'
          AND source.ift_registration_number IS NOT NULL
          AND source.registered_at IS NOT NULL)
       )
       AND EXISTS (
         SELECT 1 FROM document_templates activation_template
          WHERE activation_template.organization_id = contract_org_id
            AND activation_template.contract_template_mx_id = source.id
            AND activation_template.template_type = 'activation_contract'
            AND activation_template.is_active = 1
            AND activation_template.deleted_at IS NULL
            AND BINARY activation_template.body_md = BINARY source.template_body
            AND NOT EXISTS (
              SELECT 1 FROM document_templates competing_template
              LEFT JOIN contract_templates_mx competing_source
                ON competing_source.id = competing_template.contract_template_mx_id
               WHERE competing_template.organization_id = contract_org_id
                 AND competing_template.template_type = 'activation_contract'
                 AND competing_template.is_active = 1
                 AND competing_template.deleted_at IS NULL
                 AND (competing_source.id IS NULL OR competing_source.environment = NEW.mx_contract_environment)
                 AND (competing_source.id IS NULL OR competing_source.id <> source.id)
            )
       )
     LIMIT 1;
    IF source_org_id IS NULL OR source_org_id <> contract_org_id THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'MX contract source must belong to the contract organization';
    END IF;
  ELSEIF NEW.contract_template_mx_id IS NOT NULL OR NEW.mx_contract_environment IS NOT NULL THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Global contracts cannot carry an MX contract source or environment';
  END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_contracts_facturar_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_contracts_facturar_bu` BEFORE UPDATE ON `contracts` FOR EACH ROW BEGIN
    DECLARE v_locale VARCHAR(10);
    IF NEW.facturar = TRUE AND (OLD.facturar = FALSE OR OLD.client_id != NEW.client_id) THEN
        SELECT locale INTO v_locale FROM clients WHERE id = NEW.client_id;
        IF v_locale IS NULL OR v_locale != 'MX' THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'contracts.facturar can only be TRUE when the client has locale = ''MX''';
        END IF;
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_contracts_mx_template_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_contracts_mx_template_bu` BEFORE UPDATE ON `contracts` FOR EACH ROW BEGIN
  DECLARE contract_org_id BIGINT UNSIGNED DEFAULT NULL;
  DECLARE contract_locale VARCHAR(10) DEFAULT NULL;
  DECLARE source_org_id BIGINT UNSIGNED DEFAULT NULL;

  IF NOT (NEW.mx_contract_environment <=> OLD.mx_contract_environment) THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Contract MX environment snapshot is immutable; create a new contract';
  END IF;

  IF OLD.contract_template_mx_id IS NOT NULL
     AND (
       NOT (NEW.organization_id <=> OLD.organization_id)
       OR NEW.client_id <> OLD.client_id
     )
  THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Contract organization/client is immutable once MX provenance is frozen';
  END IF;

  IF NOT (NEW.contract_template_mx_id <=> OLD.contract_template_mx_id)
     AND (
       OLD.mx_contract_environment IS NULL
       OR OLD.status <> 'pending'
       OR OLD.first_activated_at IS NOT NULL
       OR EXISTS (
         SELECT 1 FROM signed_documents document_history
          WHERE document_history.contract_id = OLD.id
       )
     )
  THEN
    SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Contract MX source can change only while pending, unsigned, and never activated';
  END IF;

  -- Revalidate current readiness only when deliberately repairing the source
  -- of a still-pending, unsigned contract.  A source may later expire, be
  -- revoked, or have its operational template retired; that must not brick
  -- cancellation, suspension, deletion, or other updates to historical rows.
  IF NOT (NEW.contract_template_mx_id <=> OLD.contract_template_mx_id) THEN
    IF NEW.contract_template_mx_id IS NULL THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Contract MX source snapshot cannot be cleared';
    END IF;
    SELECT client.organization_id INTO contract_org_id
      FROM clients client WHERE client.id = NEW.client_id LIMIT 1;
    SET contract_org_id = COALESCE(NEW.organization_id, contract_org_id);
    SELECT organization_row.locale INTO contract_locale
      FROM organizations organization_row WHERE organization_row.id = contract_org_id LIMIT 1;
    SELECT source.organization_id INTO source_org_id
      FROM contract_templates_mx source
     WHERE source.id = NEW.contract_template_mx_id
       AND source.environment = NEW.mx_contract_environment
       AND source.deleted_at IS NULL
       AND (
         (source.environment = 'sandbox'
          AND source.status = 'sandbox_ready'
          AND source.ift_registration_number IS NULL
          AND source.registered_at IS NULL)
         OR (source.environment = 'production'
          AND source.status = 'registered'
          AND source.ift_registration_number IS NOT NULL
          AND source.registered_at IS NOT NULL)
       )
       AND EXISTS (
         SELECT 1 FROM document_templates activation_template
          WHERE activation_template.organization_id = contract_org_id
            AND activation_template.contract_template_mx_id = source.id
            AND activation_template.template_type = 'activation_contract'
            AND activation_template.is_active = 1
            AND activation_template.deleted_at IS NULL
            AND BINARY activation_template.body_md = BINARY source.template_body
            AND NOT EXISTS (
              SELECT 1 FROM document_templates competing_template
              LEFT JOIN contract_templates_mx competing_source
                ON competing_source.id = competing_template.contract_template_mx_id
               WHERE competing_template.organization_id = contract_org_id
                 AND competing_template.template_type = 'activation_contract'
                 AND competing_template.is_active = 1
                 AND competing_template.deleted_at IS NULL
                 AND (competing_source.id IS NULL OR competing_source.environment = NEW.mx_contract_environment)
                 AND (competing_source.id IS NULL OR competing_source.id <> source.id)
            )
       )
     LIMIT 1;
    IF contract_locale <> 'MX' OR source_org_id IS NULL OR source_org_id <> contract_org_id THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'MX contract source must remain attached to its Mexican organization';
    END IF;
  END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_contracts_status_fsm_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_contracts_status_fsm_bu` BEFORE UPDATE ON `contracts` FOR EACH ROW BEGIN
  DECLARE contract_org_id BIGINT UNSIGNED DEFAULT NULL;
  DECLARE current_org_locale VARCHAR(10) DEFAULT NULL;
  DECLARE current_mx_contract_environment VARCHAR(16) DEFAULT NULL;

  IF NEW.status != OLD.status THEN
    IF NOT (
           (OLD.status = 'pending'    AND NEW.status IN ('active', 'cancelled'))
        OR (OLD.status = 'active'     AND NEW.status IN ('expired', 'cancelled', 'suspended', 'terminated'))
        OR (OLD.status = 'suspended'  AND NEW.status IN ('pending', 'active', 'cancelled', 'terminated'))
        OR (OLD.status IN ('expired', 'cancelled', 'terminated') AND NEW.status IN ('pending', 'active'))
    ) THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Invalid contract status transition';
    END IF;
  END IF;

  IF NEW.status IN ('pending', 'active')
     AND (
       NEW.status != OLD.status
       OR (OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL)
     )
  THEN
    -- A locking read is essential, not just an EXISTS check. It serializes
    -- this contract-first transition with the environment switch's profile
    -- lock and closes the terminal-contract/profile write-skew window for
    -- every caller, including payment automation and direct SQL.
    SET contract_org_id = OLD.organization_id;
    IF contract_org_id IS NULL THEN
      SELECT client.organization_id INTO contract_org_id
        FROM clients client WHERE client.id = OLD.client_id LIMIT 1;
    END IF;

    SELECT organization_row.locale,
           CASE
             WHEN profile.contract_environment IS NOT NULL
               THEN profile.contract_environment
             WHEN EXISTS (
               SELECT 1
                 FROM contract_templates_mx legacy_source
                WHERE legacy_source.organization_id = organization_row.id
                  AND legacy_source.environment = 'production'
             ) THEN 'production'
             ELSE 'sandbox'
           END
      INTO current_org_locale, current_mx_contract_environment
      FROM organizations organization_row
      LEFT JOIN organization_mx_profiles profile
        ON profile.organization_id = organization_row.id
       AND profile.deleted_at IS NULL
     WHERE organization_row.id = contract_org_id
     LIMIT 1
     FOR UPDATE;

    IF current_org_locale = 'MX'
       AND (OLD.contract_template_mx_id IS NULL OR OLD.mx_contract_environment IS NULL)
    THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'MX contract renewal/activation requires a frozen contract source and environment; create a new classified MX contract';
    END IF;

    IF OLD.mx_contract_environment = 'sandbox'
       AND current_org_locale = 'MX'
       AND current_mx_contract_environment = 'production'
    THEN
      SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Sandbox contract evidence cannot return to pending or active service in production; create a new production contract';
    END IF;
  END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_contracts_radius_consistency_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_contracts_radius_consistency_bu` BEFORE UPDATE ON `contracts` FOR EACH ROW BEGIN
    DECLARE v_radius_count INT;
    IF NEW.status = 'active'
       AND OLD.status != 'active'
       AND NEW.connection_type IN ('pppoe', 'pppoe_dual')
    THEN
        SELECT COUNT(*) INTO v_radius_count
        FROM   radius
        WHERE  contract_id = NEW.id
          AND  deleted_at IS NULL;
        IF v_radius_count = 0 THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'PPPoE/PPPoE-dual contracts require at least one RADIUS account before activation';
        END IF;
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_credit_note_invoice_cap_bi`;
DELIMITER ;;
CREATE TRIGGER `trg_credit_note_invoice_cap_bi` BEFORE INSERT ON `credit_notes` FOR EACH ROW BEGIN
    DECLARE v_invoice_total   DECIMAL(10, 2);
    DECLARE v_already_credited DECIMAL(10, 2);

    IF NEW.invoice_id IS NOT NULL AND NEW.status != 'cancelled' AND NEW.deleted_at IS NULL THEN
        SELECT total INTO v_invoice_total
        FROM   invoices
        WHERE  id = NEW.invoice_id;

        SELECT COALESCE(SUM(total), 0) INTO v_already_credited
        FROM   credit_notes
        WHERE  invoice_id = NEW.invoice_id
          AND  status     != 'cancelled'
          AND  deleted_at IS NULL;

        IF v_already_credited + NEW.total > v_invoice_total THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Credit note total would exceed the linked invoice total';
        END IF;
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_credit_note_invoice_cap_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_credit_note_invoice_cap_bu` BEFORE UPDATE ON `credit_notes` FOR EACH ROW BEGIN
    DECLARE v_invoice_total   DECIMAL(10, 2);
    DECLARE v_already_credited DECIMAL(10, 2);

    IF NEW.invoice_id IS NOT NULL AND NEW.status != 'cancelled' AND NEW.deleted_at IS NULL THEN
        SELECT total INTO v_invoice_total
        FROM   invoices
        WHERE  id = NEW.invoice_id;

        SELECT COALESCE(SUM(total), 0) INTO v_already_credited
        FROM   credit_notes
        WHERE  invoice_id = NEW.invoice_id
          AND  status     != 'cancelled'
          AND  deleted_at IS NULL
          AND  id         != OLD.id;

        IF v_already_credited + NEW.total > v_invoice_total THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Credit note total would exceed the linked invoice total';
        END IF;
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_factura_publica_invoice_items_bi`;
DELIMITER ;;
CREATE TRIGGER `trg_factura_publica_invoice_items_bi` BEFORE INSERT ON `factura_publica_invoice_items` FOR EACH ROW BEGIN
    DECLARE v_invoice_status VARCHAR(20);

    SELECT status INTO v_invoice_status
    FROM   invoices
    WHERE  id = NEW.invoice_id;

    IF v_invoice_status IS NULL OR v_invoice_status != 'paid' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Cannot add invoice to factura pública: invoice must have status = ''paid''.';
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_factura_publica_invoices_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_factura_publica_invoices_bu` BEFORE UPDATE ON `factura_publica_invoices` FOR EACH ROW BEGIN
    DECLARE v_unpaid_count INT DEFAULT 0;

    IF NEW.status = 'stamped' AND OLD.status != 'stamped' THEN
        SELECT COUNT(*) INTO v_unpaid_count
        FROM   factura_publica_invoice_items fpi
        JOIN   invoices i ON i.id = fpi.invoice_id
        WHERE  fpi.factura_publica_invoice_id = NEW.id
          AND  i.status != 'paid';

        IF v_unpaid_count > 0 THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Cannot stamp factura pública: all linked invoices must have status = ''paid''. Remove or pay unpaid invoices before stamping.';
        END IF;
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_ift_statistical_reports_bi`;
DELIMITER ;;
CREATE TRIGGER `trg_ift_statistical_reports_bi` BEFORE INSERT ON `ift_statistical_reports` FOR EACH ROW BEGIN
    DECLARE v_locale VARCHAR(10);
    SELECT locale INTO v_locale FROM organizations WHERE id = NEW.organization_id;
    IF v_locale IS NULL OR v_locale != 'MX' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'ift_statistical_reports requires the referenced organization to have locale = ''MX''';
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_ift_statistical_reports_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_ift_statistical_reports_bu` BEFORE UPDATE ON `ift_statistical_reports` FOR EACH ROW BEGIN
    DECLARE v_locale VARCHAR(10);
    IF NEW.organization_id != OLD.organization_id THEN
        SELECT locale INTO v_locale FROM organizations WHERE id = NEW.organization_id;
        IF v_locale IS NULL OR v_locale != 'MX' THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'ift_statistical_reports requires the referenced organization to have locale = ''MX''';
        END IF;
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_organization_mx_profiles_bi`;
DELIMITER ;;
CREATE TRIGGER `trg_organization_mx_profiles_bi` BEFORE INSERT ON `organization_mx_profiles` FOR EACH ROW BEGIN
    DECLARE v_locale VARCHAR(10);
    SELECT locale INTO v_locale FROM organizations WHERE id = NEW.organization_id;
    IF v_locale IS NULL OR v_locale != 'MX' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'organization_mx_profiles requires the referenced organization to have locale = ''MX''';
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_organization_mx_profiles_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_organization_mx_profiles_bu` BEFORE UPDATE ON `organization_mx_profiles` FOR EACH ROW BEGIN
    DECLARE v_locale VARCHAR(10);
    IF NEW.organization_id != OLD.organization_id THEN
        SELECT locale INTO v_locale FROM organizations WHERE id = NEW.organization_id;
        IF v_locale IS NULL OR v_locale != 'MX' THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'organization_mx_profiles requires the referenced organization to have locale = ''MX''';
        END IF;
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_organizations_locale_downgrade_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_organizations_locale_downgrade_bu` BEFORE UPDATE ON `organizations` FOR EACH ROW BEGIN
    DECLARE v_has_records BOOLEAN DEFAULT FALSE;

    IF OLD.locale = 'MX' AND NEW.locale != 'MX' THEN
        -- Check organization_mx_profiles
        SELECT EXISTS(SELECT 1 FROM organization_mx_profiles WHERE organization_id = OLD.id)
        INTO v_has_records;

        IF v_has_records THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Cannot change organization locale from ''MX'': organization_mx_profiles record exists.';
        END IF;

        -- Check concession_titles
        SELECT EXISTS(SELECT 1 FROM concession_titles WHERE organization_id = OLD.id)
        INTO v_has_records;

        IF v_has_records THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Cannot change organization locale from ''MX'': concession_titles records exist.';
        END IF;

        -- Check contract_templates_mx
        SELECT EXISTS(SELECT 1 FROM contract_templates_mx WHERE organization_id = OLD.id)
        INTO v_has_records;

        IF v_has_records THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Cannot change organization locale from ''MX'': contract_templates_mx records exist.';
        END IF;

        -- Check regulatory_filings
        SELECT EXISTS(SELECT 1 FROM regulatory_filings WHERE organization_id = OLD.id)
        INTO v_has_records;

        IF v_has_records THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Cannot change organization locale from ''MX'': regulatory_filings records exist.';
        END IF;

        -- Check ift_statistical_reports
        SELECT EXISTS(SELECT 1 FROM ift_statistical_reports WHERE organization_id = OLD.id)
        INTO v_has_records;

        IF v_has_records THEN
            SIGNAL SQLSTATE '45000'
                SET MESSAGE_TEXT = 'Cannot change organization locale from ''MX'': ift_statistical_reports records exist.';
        END IF;
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_organizations_snii_locale_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_organizations_snii_locale_bu` BEFORE UPDATE ON `organizations` FOR EACH ROW BEGIN
  IF OLD.locale = 'MX' AND NEW.locale <> 'MX' AND EXISTS (
    SELECT 1 FROM snii_reporting_profiles p WHERE p.organization_id = OLD.id
  ) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cannot leave MX locale while an SNII reporting profile exists';
  END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_organizations_outbound_epoch_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_organizations_outbound_epoch_bu` BEFORE UPDATE ON `organizations` FOR EACH ROW BEGIN
    IF NOT (NEW.status <=> OLD.status)
       OR NOT (NEW.deleted_at <=> OLD.deleted_at) THEN
        SET NEW.outbound_delivery_epoch = OLD.outbound_delivery_epoch + 1;
    ELSE
        SET NEW.outbound_delivery_epoch = OLD.outbound_delivery_epoch;
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_organizations_cancel_outbound_au`;
DELIMITER ;;
CREATE TRIGGER `trg_organizations_cancel_outbound_au` AFTER UPDATE ON `organizations` FOR EACH ROW BEGIN
    IF NEW.outbound_delivery_epoch <> OLD.outbound_delivery_epoch THEN
        UPDATE snmp_trap_forwarding_deliveries
           SET status = 'cancelled', next_attempt_at = NULL,
               locked_at = NULL, claim_token = NULL,
               last_error = 'Organization lifecycle changed after this delivery was queued.'
         WHERE organization_id = OLD.id
           AND organization_epoch <> NEW.outbound_delivery_epoch
           AND status IN ('pending','retrying');
        UPDATE webhook_deliveries wd
          JOIN webhooks w ON w.id = wd.webhook_id
           SET wd.status = 'dead_letter', wd.next_retry_at = NULL,
               wd.locked_at = NULL, wd.claim_token = NULL,
               wd.response_body = NULL
         WHERE w.organization_id = OLD.id
           AND wd.organization_epoch <> NEW.outbound_delivery_epoch
           AND wd.status IN ('pending','retrying');
        UPDATE snmp_trap_forwarding_rules
           SET last_delivery_status = 'cancelled', last_delivery_at = NOW(),
               last_error = 'Organization lifecycle changed after this delivery was queued.',
               last_delivery_is_test = FALSE
         WHERE organization_id = OLD.id AND deleted_at IS NULL;
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_outages_temporal_bi`;
DELIMITER ;;
CREATE TRIGGER `trg_outages_temporal_bi` BEFORE INSERT ON `outages` FOR EACH ROW BEGIN
    IF NEW.resolved_at IS NOT NULL AND NEW.resolved_at <= NEW.started_at THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Outage resolved_at must be after started_at';
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_outages_temporal_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_outages_temporal_bu` BEFORE UPDATE ON `outages` FOR EACH ROW BEGIN
    IF NEW.resolved_at IS NOT NULL AND NEW.resolved_at <= NEW.started_at THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Outage resolved_at must be after started_at';
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_payment_alloc_payment_bi`;
DELIMITER ;;
CREATE TRIGGER `trg_payment_alloc_payment_bi` BEFORE INSERT ON `payment_allocations` FOR EACH ROW BEGIN
    DECLARE v_payment_total  DECIMAL(10, 2);
    DECLARE v_already_alloc  DECIMAL(10, 2);

    SELECT amount INTO v_payment_total
    FROM   payments
    WHERE  id = NEW.payment_id;

    SELECT COALESCE(SUM(amount), 0) INTO v_already_alloc
    FROM   payment_allocations
    WHERE  payment_id = NEW.payment_id
      AND  deleted_at IS NULL;

    IF v_already_alloc + NEW.amount > v_payment_total THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Payment allocation would exceed total payment amount';
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_payment_alloc_invoice_bi`;
DELIMITER ;;
CREATE TRIGGER `trg_payment_alloc_invoice_bi` BEFORE INSERT ON `payment_allocations` FOR EACH ROW BEGIN
    DECLARE v_invoice_total  DECIMAL(10, 2);
    DECLARE v_already_alloc  DECIMAL(10, 2);

    SELECT total INTO v_invoice_total
    FROM   invoices
    WHERE  id = NEW.invoice_id;

    SELECT COALESCE(SUM(amount), 0) INTO v_already_alloc
    FROM   payment_allocations
    WHERE  invoice_id = NEW.invoice_id
      AND  deleted_at IS NULL;

    IF v_already_alloc + NEW.amount > v_invoice_total THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Payment allocation would exceed invoice total';
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_payment_alloc_payment_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_payment_alloc_payment_bu` BEFORE UPDATE ON `payment_allocations` FOR EACH ROW BEGIN
    DECLARE v_payment_total  DECIMAL(10, 2);
    DECLARE v_already_alloc  DECIMAL(10, 2);

    SELECT amount INTO v_payment_total
    FROM   payments
    WHERE  id = NEW.payment_id;

    SELECT COALESCE(SUM(amount), 0) INTO v_already_alloc
    FROM   payment_allocations
    WHERE  payment_id = NEW.payment_id
      AND  id        != OLD.id
      AND  deleted_at IS NULL;

    IF v_already_alloc + NEW.amount > v_payment_total THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Payment allocation would exceed total payment amount';
    END IF;
END ;;
DELIMITER ;

DROP TRIGGER IF EXISTS `trg_payment_alloc_invoice_bu`;
DELIMITER ;;
CREATE TRIGGER `trg_payment_alloc_invoice_bu` BEFORE UPDATE ON `payment_allocations` FOR EACH ROW BEGIN
    DECLARE v_invoice_total  DECIMAL(10, 2);
    DECLARE v_already_alloc  DECIMAL(10, 2);

    SELECT total INTO v_invoice_total
    FROM   invoices
    WHERE  id = NEW.invoice_id;

    SELECT COALESCE(SUM(amount), 0) INTO v_already_alloc
    FROM   payment_allocations
    WHERE  invoice_id = NEW.invoice_id
      AND  id        != OLD.id
      AND  deleted_at IS NULL;

    IF v_already_alloc + NEW.amount > v_invoice_total THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Payment allocation would exceed invoice total';
    END IF;
END ;;
DELIMITER ;

