    DECLARE v_owner BIGINT UNSIGNED;
    DECLARE v_active BIGINT UNSIGNED;
    IF NEW.is_active = 1 AND NEW.deleted_at IS NULL
       AND (OLD.is_active <> 1 OR OLD.deleted_at IS NOT NULL) THEN
