         WHERE id = NEW.organization_id FOR UPDATE;
        SELECT COUNT(*) INTO v_active FROM webhooks
         WHERE organization_id = NEW.organization_id
           AND is_active = 1 AND deleted_at IS NULL AND id <> OLD.id;
